function normalizeOpacityTextureType(textureType: string) {
  const value = String(textureType || "").trim();
  return /^(opacity(?:[\s_-]*mask(?:ed)?)?|alpha|transparency|o)$/i.test(value) ? "Opacity" : value;
}

function getTextureTypeDisplayLabel(textureType: string) {
  const value = normalizeOpacityTextureType(textureType);
  if (!value) {
    return "";
  }
  const abbreviation = textureTypeAbbreviations[value];
  const displayNameByType: Record<string, string> = {
    AlbedoOpacityMasked: "Albedo + OpacityMasked",
    DiffuseOpacityMasked: "Diffuse + OpacityMasked",
    BasecolorOpacityMasked: "Basecolor + OpacityMasked",
    OpacityMaskRoughnessTranslucency: "OpacityMask + Roughness + Translucency"
  };
  const displayName = displayNameByType[value] || value;
  return abbreviation && abbreviation !== displayName ? `${displayName}（${abbreviation}）` : displayName;
}

function normalizeBaseTilingValue(value: unknown, fallback = 1) {
  const parsed = Number(String(value ?? "").trim());
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

const meshSlotBaseName = "Mesh";

function getModelLodOrder(filePath: string) {
  const base = String(filePath || "").split(/[\\/]/).pop()?.replace(/\.[^.]+$/, "") || "";
  const matched = base.match(/(?:^|[_.-])lod[_-]?(\d+)(?=$|[_.-])/i);
  return matched ? Math.max(0, Number(matched[1]) || 0) : Number.MAX_SAFE_INTEGER;
}

function isModelLodPath(filePath: string) {
  const base = String(filePath || "").split(/[\\/]/).pop()?.replace(/\.[^.]+$/, "") || "";
  return /(?:^|[_.-])lod(?:[_-]?\d+)?(?:$|[_.-])/i.test(base);
}

function getAssetModelLodEntries(asset: AssetRecord | null) {
  const meta = asset?.meta && typeof asset.meta === "object" && !Array.isArray(asset.meta)
    ? asset.meta as Record<string, unknown>
    : null;
  const entries = Array.isArray(meta?.modelLods) ? meta.modelLods : [];
  return entries
    .filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item)))
    .map((item) => ({
      filePath: String(item.file || item.path || item.uri || "").trim(),
      variantKey: String(item.variantKey ?? item.variantNumber ?? "").trim(),
      lod: Math.max(0, Number(item.lod) || 0)
    }))
    .filter((item) => item.filePath)
    .sort((left, right) => String(left.variantKey).localeCompare(String(right.variantKey), undefined, { numeric: true }) || left.lod - right.lod);
}

