function isAnimationTypeValue(value: string) {
  return ANIMATION_TYPE_SET.has(String(value || "").trim());
}

function isAnimationAffiliationValue(value: string) {
  return ANIMATION_AFFILIATION_SET.has(String(value || "").trim());
}

function resolveAnimationAffiliationValue(value = "", tags: Array<string | null | undefined> = []) {
  const fromValue = String(value || "").trim();
  if (isAnimationAffiliationValue(fromValue)) return fromValue;
  const fromTags = (tags || []).map((tag) => String(tag || "").trim()).find((tag) => isAnimationAffiliationValue(tag));
  return fromTags || ANIMATION_AFFILIATION_OPTIONS[0];
}

function resolveAnimationTypeValue(zionTags: Array<string | null | undefined> | undefined, subCategory = "") {
  const fromZion = (zionTags || []).map((tag) => String(tag || "").trim()).find((tag) => isAnimationTypeValue(tag));
  if (fromZion) return fromZion;
  const fromCategory = String(subCategory || "").trim();
  if (isAnimationTypeValue(fromCategory)) return fromCategory;
  return ANIMATION_TYPE_OPTIONS[0];
}

function withAnimationTypeFields<T extends { assetType: string; subCategory: string; zionTags: string[]; skeletonPath?: string; animationAffiliation?: string }>(form: T, assetType = form.assetType, animationType?: string, animationAffiliation?: string): T {
  if (String(assetType || "").trim().toLowerCase() !== "animation") {
    return {
      ...form,
      assetType,
      zionTags: (form.zionTags || []).filter((tag) => !isAnimationTypeValue(tag) && !isAnimationAffiliationValue(tag)),
      ...("animationAffiliation" in form ? { animationAffiliation: "" } : {})
    };
  }
  const nextType = resolveAnimationTypeValue(animationType ? [animationType] : form.zionTags, form.subCategory);
  const nextAffiliation = resolveAnimationAffiliationValue(animationAffiliation ?? form.animationAffiliation, form.zionTags);
  return {
    ...form,
    assetType,
    subCategory: nextType,
    zionTags: [nextType],
    ...("animationAffiliation" in form ? { animationAffiliation: nextAffiliation } : {}),
    ...("skeletonPath" in form ? { skeletonPath: String(form.skeletonPath || "").trim() || DEFAULT_ANIMATION_SKELETON_PATH } : {})
  };
}

function syncAnimationArchiveForm(form: ImportFormState, libraryRoot: string): ImportFormState {
  if (form.assetType !== 'animation') return form;
  form = syncAnimationPlanning(form);
  if (form.animationArchiveManual) return form;
  const fileName = getFirstFbxPath(Object.values(form.modelSlots)).replaceAll('\\', '/').split('/').pop() || '';
  const relative = suggestAnimationArchiveRelativePath(form.assetName === defaultImportForm.assetName ? fileName : form.assetName,
    resolveAnimationAffiliationValue(form.animationAffiliation, form.zionTags), resolveAnimationTypeValue(form.zionTags, form.subCategory));
  const destinationPath = joinLibraryPath(libraryRoot, relative);
  return destinationPath === form.destinationPath ? form : { ...form, destinationPath };
}

