function isAnimatedPreviewPath(filePath: string) {
  return /\.(webm|mp4|gif)$/i.test(String(filePath || "").trim());
}

function getAssetThumbnailSource(asset: AssetRecord) {
  const preview = String(asset.previewImage || asset.preview || "").trim();
  return asset.assetType === "animation"
    ? getFirstFbxPath(asset.modelFiles || []) || preview
    : preview;
}

function isMotionVideoPreviewPath(filePath: string) {
  return /\.(webm|mp4)$/i.test(String(filePath || "").trim());
}

function getFirstFbxPath(paths: Array<string | null | undefined>) {
  return paths.map((filePath) => String(filePath || "").trim()).find((filePath) => /\.fbx$/i.test(filePath)) || "";
}

function joinLibraryPath(root: string, relative: string) {
  const base = String(root || "").replace(/[\\/]+$/, "");
  const child = String(relative || "").replace(/^[\\/]+/, "").replace(/\//g, "\\");
  if (!base) return child;
  if (!child) return base;
  return `${base}\\${child}`;
}

function normalizePathForCompare(value: string) {
  return String(value || "").replace(/\//g, "\\").replace(/\\+$/, "").toLowerCase();
}

function isPathUnderLibrary(root: string, candidate: string) {
  const library = normalizePathForCompare(root);
  const target = normalizePathForCompare(candidate);
  return Boolean(library && target) && (target === library || target.startsWith(`${library}\\`));
}

function readLastImportDestinations(): Record<string, string> {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(LAST_IMPORT_DESTINATION_STORAGE_KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function rememberImportDestination(assetType: string, destinationPath: string) {
  const key = String(assetType || "").trim().toLowerCase();
  const dest = String(destinationPath || "").trim();
  if (!key || !dest) return;
  window.localStorage.setItem(LAST_IMPORT_DESTINATION_STORAGE_KEY, JSON.stringify({
    ...readLastImportDestinations(),
    [key]: dest
  }));
}

function forgetImportDestination(assetType: string) {
  const key = String(assetType || "").trim().toLowerCase();
  if (!key) return;
  const next = { ...readLastImportDestinations() };
  delete next[key];
  window.localStorage.setItem(LAST_IMPORT_DESTINATION_STORAGE_KEY, JSON.stringify(next));
}
