function resolveExportStageLabel(percent: number, language: "zh" | "en" = "zh", target = "Unreal") {
  if (language === "en") {
    if (percent < 35) return "Preparing import";
    if (percent < 55) return "Generating import manifest";
    if (percent < 75) return "Preparing and compressing assets";
    if (percent < 100) return `Importing into ${target}`;
    return "Import complete";
  }
  if (percent < 35) return "准备导入任务";
  if (percent < 55) return "生成导入清单";
  if (percent < 75) return "整理与压缩资产";
  if (percent < 100) return `${target} 导入中`;
  return "导入完成";
}

function formatImportButtonStage(stage: string, percent: number, language: "zh" | "en", target = "Unreal") {
  if (language === "en" && /[\u3400-\u9fff]/.test(stage)) return resolveExportStageLabel(percent, language, target);
  const label = (stage || resolveExportStageLabel(percent, language, target)).replace(/^导出阶段\s*[:：]\s*/, "").trim();
  return /^导入模型\s*[:：]/.test(label) ? (language === "en" ? `Importing into ${target}` : `${target} 导入中`) : label;
}

const TextureEntryRow = memo(({
  t,
  entry,
  usedByOthers,
  textureTypeOptions,
  normalMapFormat,
  batchNormalMapFormat,
  onNormalMapFormatChange,
  onTextureTypeChange,
  onDrop,
  onPick,
  onRemove,
  isPathMissing,
  disableRemove,
  hideTextureTypeSelect,
  lockTextureTypeSelect
}: {
  t: (zh: string, en: string) => string;
  entry: TextureEntry;
  usedByOthers: Set<string>;
  textureTypeOptions: string[];
  normalMapFormat?: "dx" | "opengl" | null;
  batchNormalMapFormat?: boolean;
  onNormalMapFormatChange: (format: "dx" | "opengl") => void;
  onTextureTypeChange: (nextType: string) => void;
  onDrop: (event: React.DragEvent<HTMLDivElement>) => void;
  onPick: () => void;
  onRemove: () => void;
  isPathMissing: (filePath: string) => boolean;
  disableRemove?: boolean;
  hideTextureTypeSelect?: boolean;
  lockTextureTypeSelect?: boolean;
}) => {
  const normalizedTextureType = String(entry.textureType || "").trim().toLowerCase();
  const isNormalTexture = normalizedTextureType === "normal" || normalizedTextureType === "normalbump";

  // Try to determine the format from the file extension
  const ext = (entry.filePath || "").split('.').pop()?.toUpperCase() || "";
  const showFormatTag = normalizedTextureType === "displacement" && ext;

  return (
    <div className="texture-row texture-slot-row">
      <div style={{ position: "relative" }}>
        {!hideTextureTypeSelect ? (
          <DarkSelect
            value={entry.textureType}
            ariaLabel={t("贴图类型", "Texture Type")}
            className="settings-dark-select texture-type-dark-select"
            lockOpen={Boolean(lockTextureTypeSelect)}
            hideChevron={Boolean(lockTextureTypeSelect)}
            options={[
              { value: "", label: t("选择类型...", "Select Type...") },
              ...textureTypeOptions.map((textureType) => ({
                value: textureType,
                label: getTextureTypeDisplayLabel(textureType),
                disabled: usedByOthers.has(textureType)
              }))
            ]}
            onChange={(nextValue) => onTextureTypeChange(nextValue)}
          />
        ) : (
          <label className="texture-check">
            <span>{getTextureTypeDisplayLabel(entry.textureType) || "HDR"}</span>
          </label>
        )}
        {showFormatTag && (
          <div style={{
            position: "absolute",
            right: "34px",
            top: "50%",
            transform: "translateY(-50%)",
            fontSize: "10px",
            fontWeight: 800,
            padding: "2px 4px",
            borderRadius: "4px",
            pointerEvents: "none",
            background: ext === "EXR" ? "rgba(189, 147, 249, 0.15)" : "rgba(130, 130, 130, 0.15)",
            color: ext === "EXR" ? "#bd93f9" : "#a0a0a0",
            border: ext === "EXR" ? "1px solid rgba(189, 147, 249, 0.3)" : "1px solid rgba(130, 130, 130, 0.2)"
          }}>
            {ext}
          </div>
        )}
      </div>
      <div
        className="drop-target texture-drop"
        style={{ flex: 1, width: "100%" }}
        onDragEnter={(event) => event.preventDefault()}
        onDragOverCapture={(event) => {
          event.preventDefault();
          event.stopPropagation();
        }}
        onDragOver={(event) => event.preventDefault()}
        onDrop={onDrop}
      >
        <div className="path-display-row" title={entry.filePath || ""}>
          <div className={`slot-input-wrap${isNormalTexture ? " with-flip" : ""}${isNormalTexture && batchNormalMapFormat ? " with-batch-flip" : ""}`}>
            <input
              className={`settings-input${isPathMissing(entry.filePath || "") ? " missing-file-path" : ""}`}
              value={entry.filePath || ""}
              readOnly
              title={entry.filePath || t("选择或拖拽贴图文件", "Select or drop a texture file")}
              placeholder={t("选择或拖拽贴图文件", "Select or drop a texture file")}
            />
            {isNormalTexture && batchNormalMapFormat ? (
              <DarkSelect
                value={normalMapFormat || ""}
                mixed={normalMapFormat === null}
                disabled={normalMapFormat === undefined}
                ariaLabel={t("批量修改当前贴图组的法线格式", "Batch normal format for this texture group")}
                className="normal-format-select"
                options={[{ value: "dx", label: "DX" }, { value: "opengl", label: "OpenGL" }]}
                onChange={(format) => onNormalMapFormatChange(format as "dx" | "opengl")}
              />
            ) : isNormalTexture && normalMapFormat && (
              <button
                type="button"
                className={`path-icon-btn flip-inline-btn ${normalMapFormat === "opengl" ? "opengl" : "dx"}`}
                title={t("点击切换 DX / OpenGL 法线格式（当前贴图组）", "Click to switch DX / OpenGL normal format for this texture group")}
                onClick={(event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  onNormalMapFormatChange(normalMapFormat === "opengl" ? "dx" : "opengl");
                }}
              >
                {normalMapFormat === "opengl" ? "OpenGL" : "DX"}
              </button>
            )}
            <button
              type="button"
              className="path-icon-btn browse-icon-btn"
              title={t("浏览", "Browse")}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                onPick();
              }}
            >
              <Icon name="folder" />
            </button>
          </div>
          {!disableRemove && (
            <button
              type="button"
              className="path-icon-btn remove-icon-btn"
              title={t("移除", "Remove")}
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                onRemove();
              }}
            >
              <Icon name="trash" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
});

const PreviewDropSlot = memo(({
  t,
  previewImagePath,
  busy,
  onPick,
  onDrop,
  onPasteImage,
  onRemove,
  onCutout,
  onQuickBackgroundRemove,
  isPathMissing,
  emptyLabel
}: {
  t: (zh: string, en: string) => string;
  previewImagePath: string;
  busy: boolean;
  onPick: () => void;
  onDrop: (event: React.DragEvent<HTMLDivElement>) => void;
  onPasteImage?: (file: File) => void;
  onRemove: () => void;
  onCutout?: () => void;
  onQuickBackgroundRemove?: () => void;
  isPathMissing: (filePath: string) => boolean;
  emptyLabel?: string;
}) => {
  const [displayPreviewPath, setDisplayPreviewPath] = useState(previewImagePath);
  const slotRef = useRef<HTMLDivElement>(null);
  const hoveredRef = useRef(false);

  useEffect(() => {
    if (!onPasteImage) return;
    let requestId = 0;
    let active = true;
    const canPaste = (target: EventTarget | null) => {
      if (busy || !(target instanceof HTMLElement)) return false;
      // Keep text-field paste intact even when the pointer is over the preview.
      if (target.closest("input, textarea, [contenteditable]:not([contenteditable='false'])")) return false;
      return hoveredRef.current || Boolean(slotRef.current?.contains(target));
    };
    const handlePaste = (event: ClipboardEvent) => {
      if (event.defaultPrevented || !canPaste(event.target)) return;
      const image = Array.from(event.clipboardData?.files || []).find((file) =>
        file.type.startsWith("image/") || /\.(png|jpe?g|tiff?|hdr|tga|webp|bmp)$/i.test(file.name)
      );
      if (!image) return;
      requestId++;
      event.preventDefault();
      event.stopPropagation();
      onPasteImage(image);
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.altKey || !(event.ctrlKey || event.metaKey) || event.key.toLowerCase() !== "v" || !canPaste(event.target)) return;
      const readClipboardImage = window.arkhive?.readClipboardImage;
      if (!readClipboardImage) return;
      const currentRequest = ++requestId;
      // Some Windows clipboard sources do not dispatch an image paste event.
      // Handle the shortcut directly and avoid a second default Chromium paste.
      event.preventDefault();
      event.stopPropagation();
      void readClipboardImage().then((image) => {
        if (!active || currentRequest !== requestId || !image || !canPaste(document.activeElement)) return;
        onPasteImage(new File([new Uint8Array(image.bytes)], image.name));
      }).catch(() => {
        // Preserve the current preview if the system clipboard cannot be read.
      });
    };
    document.addEventListener("paste", handlePaste);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      active = false;
      document.removeEventListener("paste", handlePaste);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [busy, onPasteImage]);

  useEffect(() => {
    let active = true;
    const nextPath = String(previewImagePath || "").trim();
    if (!nextPath) {
      setDisplayPreviewPath("");
      return () => {
        active = false;
      };
    }
    const bridge = window.arkhive;
    if (!bridge || typeof bridge.getPreviewThumbnail !== "function") {
      setDisplayPreviewPath(nextPath);
      return () => {
        active = false;
      };
    }
    void bridge.getPreviewThumbnail(nextPath).then((resolvedPath: string) => {
      if (!active) {
        return;
      }
      setDisplayPreviewPath(String(resolvedPath || nextPath).trim() || nextPath);
    }).catch(() => {
      if (!active) {
        return;
      }
      setDisplayPreviewPath(nextPath);
    });
    return () => {
      active = false;
    };
  }, [previewImagePath]);

  return (
    <div
      ref={slotRef}
      className="drop-target preview-drop-target"
      title={[previewImagePath, onPasteImage ? t("Ctrl+V 粘贴预览图", "Ctrl+V to paste a preview image") : ""].filter(Boolean).join("\n")}
      tabIndex={onPasteImage ? 0 : undefined}
      aria-label={onPasteImage ? t("预览图（Ctrl+V 粘贴）", "Preview image (Ctrl+V to paste)") : undefined}
      onMouseEnter={() => { hoveredRef.current = true; }}
      onMouseLeave={() => { hoveredRef.current = false; }}
      onClick={onPick}
      onDragEnter={(event) => event.preventDefault()}
      onDragOverCapture={(event) => {
        event.preventDefault();
        event.stopPropagation();
      }}
      onDragOver={(event) => event.preventDefault()}
      onDrop={onDrop}
    >
      <div className="preview-slot-actions">
        {previewImagePath && onQuickBackgroundRemove && (
          <button
            type="button"
            className="path-icon-btn preview-action-btn"
            title={t("自动去背景", "Remove background")}
            aria-label={t("自动去背景", "Remove background")}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              onQuickBackgroundRemove();
            }}
            disabled={busy}
          >
            <Icon name="wand" />
          </button>
        )}
        {previewImagePath && onCutout && (
          <button
            type="button"
            className="path-icon-btn preview-action-btn"
            title={t("抠图 / 自动去背景", "Cutout / Remove background")}
            aria-label={t("抠图 / 自动去背景", "Cutout / Remove background")}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              onCutout();
            }}
            disabled={busy}
          >
            <Icon name="preview-cutout" />
          </button>
        )}
        {previewImagePath && (
          <button
            type="button"
            className="path-icon-btn preview-action-btn"
            title={t("移除", "Remove")}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              onRemove();
            }}
            disabled={busy}
          >
            <Icon name="close" />
          </button>
        )}
      </div>
      <div className="preview-drop-content">
        {previewImagePath ? (
          <>
            {isMotionVideoPreviewPath(previewImagePath) ? (
              <AnimationPreviewVideo
                className="preview-slot-image"
                src={getPreviewUrl(displayPreviewPath || previewImagePath)}
              />
            ) : (
              <img className="preview-slot-image" src={getPreviewUrl(displayPreviewPath || previewImagePath)} alt="preview" />
            )}
            <div className={`preview-slot-filename${isPathMissing(previewImagePath) ? " missing-file-path" : ""}`} title={previewImagePath}>
              {String(previewImagePath || "").split(/[\\/]/).pop() || previewImagePath}
            </div>
          </>
        ) : (
          <div className="preview-drop-empty">
            <Icon name="preview-image-add" />
            <span>{emptyLabel || t("预览图", "Preview image")}</span>
          </div>
        )}
      </div>
    </div>
  );
});

function getTextureAnalysis(asset: AssetRecord | null): TextureAnalysis | null {
  if (!asset) {
    return null;
  }
  const meta = asset.meta && typeof asset.meta === "object" ? asset.meta as Record<string, unknown> : null;
  const candidates = [asset.textureAnalysis, meta?.textureAnalysis];
  for (const candidate of candidates) {
    if (candidate && typeof candidate === "object" && !Array.isArray(candidate)) {
      return candidate as TextureAnalysis;
    }
  }
  return null;
}

type CharacterPackageItem = {
  originalName: string;
  normalizedName: string;
  storedPath: string;
  role: string;
  formId?: string;
  unresolvedFormToken?: string;
  componentRole?: string;
  componentName?: string;
  sharedAcrossForms?: boolean;
  materialName: string;
  textureGroup: string;
  textureType: string;
  size: number;
  triangleCount: number | null;
};

type CharacterTextureGroupInfo = {
  name: string;
  maps: Array<{ type: string; fileName: string; storedPath: string }>;
};

type CharacterAssetInfo = {
  family: string;
  category: string;
  fields: Partial<CharacterImportFields>;
  maturity: string;
  fileCount: number;
  files: CharacterPackageItem[];
  modelParts: CharacterPackageItem[];
  textureGroups: CharacterTextureGroupInfo[];
  metrics: { modelCount: number; knownTriangleCount: number; unknownModelCount: number; totalTriangleCount: number | null; overBudget: boolean };
};

function getCharacterAssetInfo(asset: AssetRecord | null): CharacterAssetInfo | null {
  if (!asset || !isCharacterAssetType(asset.assetType)) return null;
  const meta = asset.meta && typeof asset.meta === "object" ? asset.meta as Record<string, unknown> : {};
  const fields = meta.character && typeof meta.character === "object" && !Array.isArray(meta.character)
    ? meta.character as Partial<CharacterImportFields>
    : {};
  const manifest = meta.characterManifest && typeof meta.characterManifest === "object" && !Array.isArray(meta.characterManifest)
    ? meta.characterManifest as { fileCount?: unknown; maturity?: unknown; files?: unknown; metrics?: unknown }
    : null;
  const manifestFiles: CharacterPackageItem[] = Array.isArray(manifest?.files)
    ? activeCharacterFiles(asset).filter((item): item is typeof item & Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))).map((item) => ({
      originalName: String(item.originalName || ""),
      normalizedName: String(item.normalizedName || ""),
      storedPath: String(item.storedPath || ""),
      role: String(item.role || "other"),
      formId: String(item.formId || ""),
      unresolvedFormToken: String(item.unresolvedFormToken || ""),
      componentRole: String(item.componentRole || ""),
      componentName: String(item.componentName || ""),
      sharedAcrossForms: item.sharedAcrossForms === true,
      materialName: String(item.materialName || ""),
      textureGroup: String(item.textureGroup || ""),
      textureType: String(item.textureType || ""),
      size: Math.max(0, Number(item.size) || 0),
      triangleCount: typeof item.triangleCount === "number" && Number.isFinite(item.triangleCount) ? Math.max(0, Math.floor(item.triangleCount)) : null
      }))
    : [];
  const modelParts = manifestFiles.filter((item) => ["model", "skeletalMesh", "staticMesh"].includes(item.role));
  if (modelParts.length === 0) {
    (Array.isArray(asset.modelFiles) ? asset.modelFiles : []).forEach((filePath) => modelParts.push({ originalName: "", normalizedName: characterFileBaseName(filePath), storedPath: filePath, role: "model", materialName: "", textureGroup: "", textureType: "", size: 0, triangleCount: null }));
  }
  const textureItems = manifestFiles.filter((item) => item.role === "texture");
  if (!Array.isArray(manifest?.files)) {
    (Array.isArray(asset.textureFiles) ? asset.textureFiles : []).filter(isAllowedCharacterTextureFile).forEach((filePath) => textureItems.push({ originalName: "", normalizedName: characterFileBaseName(filePath), storedPath: filePath, role: "texture", materialName: "", textureGroup: "", textureType: "", size: 0, triangleCount: null }));
  }
  const textureGroups = new Map<string, CharacterTextureGroupInfo>();
  for (const item of textureItems) {
    const normalizedFileName = item.normalizedName || characterFileBaseName(item.storedPath) || item.originalName;
    const inferredNormalizedGroup = tFallbackTextureGroupName(normalizedFileName).replace(/^T_/, "MI_");
    const groupName = item.materialName || inferredNormalizedGroup || inferCharacterTextureGroup(item.originalName) || tFallbackTextureGroupName(item.originalName);
    const key = groupName.toLowerCase();
    if (!key) continue;
    const group: CharacterTextureGroupInfo = textureGroups.get(key) || { name: groupName, maps: [] };
    const suffix = getFamilyTextureMapCode(normalizedFileName.replace(/\.[^.]+$/, "")) || item.textureType || "MAP";
    group.maps.push({ type: suffix, fileName: normalizedFileName, storedPath: item.storedPath });
    textureGroups.set(key, group);
  }
  const rawMetrics = (meta.characterMetrics && typeof meta.characterMetrics === "object" ? meta.characterMetrics : manifest?.metrics) as Record<string, unknown> | undefined;
  const primaryModels = modelParts.filter(item => !/_LOD[1-9]\d*(?=\.[^.]+$)/i.test(item.normalizedName || item.storedPath));
  const knownTriangleCount = rawMetrics ? Math.max(0, Number(rawMetrics.knownTriangleCount) || 0)
    : primaryModels.reduce((sum, item) => sum + (item.triangleCount ?? 0), 0);
  const unknownModelCount = rawMetrics ? Math.max(0, Number(rawMetrics.unknownModelCount) || 0)
    : primaryModels.filter(item => item.triangleCount === null).length;
  const metrics = asset.assetType === "monster" ? monsterBodyMetrics(manifestFiles) : { modelCount: rawMetrics ? Math.max(0, Number(rawMetrics.modelCount) || 0) : primaryModels.length,
    knownTriangleCount, unknownModelCount, totalTriangleCount: unknownModelCount ? null : knownTriangleCount,
    overBudget: rawMetrics?.overBudget === true || knownTriangleCount > 300000 };
  return {
    family: String(asset.assetType || ""),
    category: String(meta.category || ""),
    fields,
    maturity: String(fields.maturity || manifest?.maturity || "wip"),
    fileCount: Math.max(manifestFiles.length, Number(manifest?.fileCount) || 0),
    files: manifestFiles,
    modelParts,
    textureGroups: [...textureGroups.values()],
    metrics
  };
}

function tFallbackTextureGroupName(fileName: string) {
  return String(fileName || "").replace(/\.[^.]+$/, "").replace(/_(?:ORM|D|N|A)$/i, "").replace(/^T_/i, "");
}

function characterFileBaseName(filePath: string) {
  return String(filePath || "").replace(/\\/g, "/").split("/").pop() || "";
}

function characterPackageModelSlots(assetType: string, files: string[]) {
  const models = files.filter(filePath => assetType === "suit"
    ? classifyCharacterPackageFile(filePath) === "model"
    : ["skeletalMesh", "staticMesh"].includes(classifyFamilyPackageFile(assetType, filePath).role));
  return Object.fromEntries(models.map((filePath, index) => [index === 0 ? "Mesh" : `Mesh${String(index + 1).padStart(2, "0")}`, filePath]));
}

function inferMixedWeaponIdentity(files: string[]) {
  const source = heroPackageModelFiles(files)[0] || files[0] || "Weapon";
  const subject = characterFileBaseName(source).replace(/\.[^.]+$/, "").replace(/^(?:SK|SM)_/i, "").replace(/_LOD\d+$/i, "");
  const type = WEAPON_TYPES.find(type => new RegExp(`(?:^|_)${type}(?=_|\\d|$)`, 'i').test(subject)) || '';
  const fields = inferCharacterFields('weapon', files);
  const number = subject.match(/(?:^|_)[A-Za-z]+_?(\d{1,3})(?:_|$)/)?.[1];
  const serial = fields.serial || (number ? number.padStart(3, '0') : '');
  return { type, category: weaponCategory(type), serial, name: fields.name || '', assetName: subject };
}

function filterCharacterTextureEntries(entries: TextureEntry[], files: string[]) {
  const pathKey = (value: string) => String(value || "").trim().replace(/\//g, "\\").toLowerCase();
  const accepted = new Set(files.map(pathKey));
  return entries.filter(entry => !entry.filePath || accepted.has(pathKey(entry.filePath)));
}

function setCharacterPackageFileIncluded(form: ImportFormState, filePath: string, included: boolean): ImportFormState {
  const excluded = form.characterManualExclusions || [];
  const saved = excluded.find(item => item.filePath === filePath);
  if (included ? !saved || !partitionCharacterPackageFiles([filePath]).accepted.length : !form.characterPackageFiles.includes(filePath)) return form;
  const files = included ? [...new Set([...form.characterPackageFiles, filePath])] : form.characterPackageFiles.filter(file => file !== filePath);
  const textureEntries = included ? [...form.textureEntries, ...saved!.textureEntries] : filterCharacterTextureEntries(form.textureEntries, files);
  const changesModels = /\.(fbx|obj|abc|gltf|glb)$/i.test(filePath);
  const changesPreview = changesModels && !/_LOD[1-9]\d*\.[^.]+$/i.test(filePath) || /\.(png|jpe?g|tiff?|tga|webp|bmp|exr|hdr|dds)$/i.test(filePath);
  const slots = changesModels ? characterPackageModelSlots(form.assetType, files) : form.modelSlots;
  const automaticPreviews = [...Object.values(form.characterPreviewPaths), ...(form.characterPartPreviews || []).flatMap(part => Object.values(part.paths))];
  return { ...form, characterPackageFiles: files, textureEntries,
    characterManualExclusions: included ? excluded.filter(item => item !== saved) : [...excluded, {
      filePath, textureEntries: form.textureEntries.filter(entry => !textureEntries.includes(entry))
    }],
    modelSlots: slots, enabledModelTypes: changesModels ? Object.keys(slots) : form.enabledModelTypes,
    modelVariantKeys: changesModels ? {} : form.modelVariantKeys, modelLodFiles: changesModels ? {} : form.modelLodFiles,
    characterLodConfirmation: '', characterFields: { ...form.characterFields, confirmed: false },
    ...(changesPreview ? { characterPreviewPaths: {front: '', left: '', right: '', back: ''}, characterPartPreviews: [], characterPreviewError: '',
      previewImagePath: automaticPreviews.includes(form.previewImagePath) ? '' : form.previewImagePath,
      characterExtraPreviewPaths: form.characterExtraPreviewPaths?.filter(path => !automaticPreviews.includes(path)) } : {})
  };
}

function pruneCharacterImportFiles(form: ImportFormState): ImportFormState {
  if (!isCharacterAssetType(form.assetType)) return form;
  const rejected = partitionCharacterPackageFiles(form.characterPackageFiles).excluded;
  const staleExclusions = (form.characterManualExclusions || []).filter(item => !partitionCharacterPackageFiles([item.filePath]).accepted.length);
  if (!rejected.length && !staleExclusions.length) return form;
  const next = rejected.reduce((draft, file) => setCharacterPackageFileIncluded(draft, file, false), form);
  return { ...next, characterExcludedFiles: [...new Set([...(form.characterExcludedFiles || []), ...rejected, ...staleExclusions.map(item => item.filePath)])],
    characterManualExclusions: (next.characterManualExclusions || []).filter(item => partitionCharacterPackageFiles([item.filePath]).accepted.length > 0) };
}

function mapSubCategoryToOptionLabel(assetType: string, raw: string) {
  const norm = (s: string) => String(s || "").trim().toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ");
  const options = subCategoryOptionsByAssetType[String(assetType || "").trim().toLowerCase()] || ["Other"];
  const target = norm(raw);
  const found = options.find((opt) => norm(opt) === target);
  return found || raw || "";
}

function resolveImportSubCategory(assetType: string, metadataCategory: unknown) {
  const options = subCategoryOptionsByAssetType[String(assetType || "").trim().toLowerCase()] || ["Other"];
  const fallback = options[0] || "";
  const raw = String(metadataCategory || "").trim();
  if (!raw) {
    return fallback;
  }
  const norm = (s: string) => String(s || "").trim().toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ");
  const target = norm(raw);
  return options.find((option) => norm(option) === target) || fallback;
}

function CollisionAction({ t }: { t: (zh: string, en: string) => string }) {
  const label = t("碰撞", "Collision");
  const title = t("已检测到碰撞体", "Collision mesh detected");
  return (
    <div className="icon-action-col" title={title}>
      <div style={{ width: 48, height: 48, display: "flex", alignItems: "flex-end", justifyContent: "center", padding: 4 }}>
        <Icon name="cube" />
      </div>
      <span className="icon-label" style={{ textTransform: "none" }}>{label}</span>
    </div>
  );
}

function ResolutionAction({ summary, t }: { summary: TextureResolutionSummary | null; t: (zh: string, en: string) => string }) {
  if (!summary) return null;
  const label = t("分辨率", "Resolution");
  const title = summary.compressed
    ? t(
        `入库分辨率 ${summary.actualLabel}，源纹理 ${summary.sourceLabel}（已压缩）`,
        `Stored resolution ${summary.actualLabel}; source ${summary.sourceLabel} (compressed)`
      )
    : t(
        `纹理分辨率 ${summary.actualLabel}`,
        `Texture resolution ${summary.actualLabel}`
      );
  return (
    <div className="icon-action-col" title={title}>
      <div style={{ width: 48, height: 48, display: "flex", alignItems: "flex-end", justifyContent: "center", padding: 4 }}>
        <span className="resolution-badge">{summary.actualLabel}</span>
      </div>
      <span className="icon-label" style={{ textTransform: "none" }}>{label}</span>
    </div>
  );
}

const AssetCard = memo(({
  asset,
  previewLoader,
  animationCoverQueue,
  isSelected,
  selectedMeshKind,
  previewWorkState,
  isFavorite,
  onSelect,
  onToggleSuitParts,
  onAddSuitPart,
  onToggle,
  onToggleFavorite,
  onContextMenu,
  onQuickExport,
  exportDisabled,
  exportTitle,
  exportTarget = "unreal",
  exportDimmed = false,
  exportLoading = false,
  exportProgress = 0,
  monsterFormCounter = "01/01",
  variantId,
  variantAssets,
  savingProgress = -1,
  uiLanguage,
  animationProjectPath = '',
  x, y, width, height
}: {
  asset: AssetRecord;
  previewLoader: PreviewLoader;
  animationCoverQueue?: AnimationCoverQueue;
  isSelected: boolean;
  selectedMeshKind?: "staticMesh" | "skeletalMesh";
  previewWorkState?: 'queued' | 'running' | 'failed';
  isFavorite: boolean;
  onSelect: (assetId: string, meshKind?: "staticMesh" | "skeletalMesh") => void;
  onToggleSuitParts: (assetId: string) => void;
  onAddSuitPart?: (ownerId: string) => void;
  onToggle: (assetId: string) => void;
  onToggleFavorite: (assetId: string) => void;
  onContextMenu: (event: React.MouseEvent, assetId: string) => void;
  onQuickExport: (assetId: string) => void;
  exportDisabled: boolean;
  exportDimmed?: boolean;
  exportLoading?: boolean;
  exportProgress?: number;
  monsterFormCounter?: string;
  variantId?: string;
  variantAssets?: AssetRecord[];
  savingProgress?: number;
  uiLanguage: "zh" | "en";
  animationProjectPath?: string;
  exportTitle?: string;
  exportTarget?: "unreal" | "blender" | "3dcoat";
  x: number;
  y: number;
  width: number;
  height: number;
}) => {
  const sourcePath = String(asset.previewImage || asset.preview || "").trim();
  const [failedAnimationCover, setFailedAnimationCover] = useState("");
  const failedLegacyCover = Boolean(sourcePath && failedAnimationCover === sourcePath);
  const thumbnailSource = failedLegacyCover ? getFirstFbxPath(asset.modelFiles || []) : getAssetThumbnailSource(asset);
  const cardRef = useRef<HTMLElement>(null);
  const animationModelPath = asset.source === "custom" && asset.assetType === "animation" && /\.fbx$/i.test(thumbnailSource)
    ? thumbnailSource : "";
  const { id: assetId, previewSkeletonPath, previewSkeletalMeshPath } = asset;
  useEffect(() => {
    if (!cardRef.current || !animationModelPath) return;
    return animationCoverQueue?.observe(cardRef.current, {
      assetId, modelPath: animationModelPath, skeletonPath: previewSkeletonPath, skeletalMeshPath: previewSkeletalMeshPath
    });
  }, [animationCoverQueue, animationModelPath, assetId, previewSkeletonPath, previewSkeletalMeshPath]);
  const cardPreviewItem = (asset.previewImages || []).find(item => item.tags.includes("cover")) || (asset.previewImages || []).find(item => item.path === sourcePath);
  const previewReloading = characterImageIsReloading(asset, cardPreviewItem?.tags);
  const actionLoading = !isFolderOnlyAsset(asset) && exportLoading;
  const cardTargetName = exportTarget === "blender" ? "Blender" : exportTarget === "3dcoat" ? "3DCoat" : "Unreal Engine";
  const savePercent = Math.round(Math.max(0, Math.min(100, savingProgress)));
  const saveComplete = savePercent >= 100;
  const characterInfo = getCharacterAssetInfo(asset);
  const componentView = asset.meta?.componentView as { parentId: string; missingTextures?: boolean; visibleMeshKind?: "staticMesh" | "skeletalMesh"; meshSlots?: Record<"staticMesh" | "skeletalMesh", { hasModel?: boolean; previewPath?: string; previewState?: string }> } | undefined;
  const componentMeshSlots = componentView?.meshSlots;
  const cardAssetName = characterInfo?.family === 'monster' && !componentView
    ? String(characterInfo.fields.name || characterDisplayName(asset)) : characterDisplayName(asset);
  const cardWeapons = characterOwnedWeapons(asset, variantId, variantAssets);
  const cardVariant = variantId ? monsterVariantGroups([asset]).find(variant => variant.id === variantId)?.name || variantId : monsterVariantLabel(asset);
  const cardAnimationLabels = String(asset.assetType || "").trim().toLowerCase() === "animation" ? asset.animationLabels || [] : [];
  const cardAnimationGameTag = String(asset.assetType || "").trim().toLowerCase() === "animation" ? asset.animationGameTag : undefined;
  const characterChineseName = String(characterInfo?.fields.displayNameZh || "").trim();
  const heroPart = characterInfo ? heroPartKind(characterInfo.fields) : '';
  const cardManifest = asset.meta?.characterManifest as { files?: Array<{ storedPath?: string; normalizedName?: string }> } | undefined;
  const hairModelPaths = heroPart === 'Hair' ? [...(asset.modelFiles || []), ...(cardManifest?.files || []).map(file => file.storedPath || file.normalizedName || '')] : [];
  const heroPartLabel = heroPart === 'Hair' ? [hairModelPaths.some(file => /\.fbx$/i.test(file)) && 'HairCard', hairModelPaths.some(file => /\.abc$/i.test(file)) && 'Groom'].filter(Boolean).join(' / ') || (uiLanguage === 'en' ? 'Hair' : '头发') : heroPart === 'Face' ? (uiLanguage === 'en' ? 'Face' : '脸部') : '';
  const outfitClassLabel = characterInfo?.family === "suit" ? ({ Light: ["轻甲", "Light"], Medium: ["中甲", "Medium"], Heavy: ["重甲", "Heavy"] } as Record<string, string[]>)[characterInfo.fields.suitClass || ""]?.[uiLanguage === "en" ? 1 : 0] : "";
  const saveLabel = saveComplete
    ? (uiLanguage === "en" ? "Saved" : "保存完成")
    : (uiLanguage === "en" ? "Saving" : "正在保存");
  if (asset.meta?.missingSuitPart) return <article className="character-missing-part" style={{ transform: `translate3d(${x}px, ${y}px, 0)`, width, height }}>
    <span>{uiLanguage === 'en' ? `${asset.meta.missingSuitPart} not uploaded yet` : `尚未上传 ${asset.meta.missingSuitPart} 部件`}</span>
    <button type="button" className="character-add-part" title={uiLanguage === 'en' ? 'Add part' : '添加部件'} aria-label={uiLanguage === 'en' ? 'Add part' : '添加部件'} disabled={!onAddSuitPart} onClick={() => onAddSuitPart?.(asset.id.split('::missing-part::')[0])}>＋</button>
  </article>;
  return (
    <article
      ref={cardRef}
      id={`asset-card-${monsterCardOccurrence(asset.id, variantId)}`}
      data-asset-id={asset.id}
      data-variant-id={variantId}
      data-character-component={componentView || asset.id.includes("::part::") ? "true" : undefined}
      title={cardAssetName}
      onDoubleClick={characterInfo?.family === 'suit' && !componentView && !heroPartKind(characterInfo.fields) ? event => {
        if (savingProgress >= 0 || event.ctrlKey || event.metaKey || event.shiftKey || (event.target as HTMLElement).closest('button, input, a')) return;
        event.preventDefault(); event.stopPropagation(); onToggleSuitParts(asset.id);
      } : undefined}
      className={`card ${isSelected ? "active" : ""} ${getCardWidthClass(asset)} ${savingProgress >= 0 ? "saving" : ""} ${String(asset.assetType || "").trim().toLowerCase() === "hdri" ? "hdri" : ""} ${characterInfo ? "character-card" : ""}`}
      style={{ ...(characterInfo ? { translate: `${x}px ${y}px`, transform: "perspective(1000px) rotateX(var(--card-tilt-x, 0deg)) rotateY(var(--card-tilt-y, 0deg))" } : { transform: `translate3d(${x}px, ${y}px, 0)` }), width, height, "--character-card-scale": width / 240 } as CSSProperties & { translate?: string; "--character-card-scale": number }}
      onPointerMove={characterInfo ? (event) => {
        const card = event.currentTarget;
        if (variantId !== undefined || card.dataset.characterComponent === "true" || event.pointerType === "touch" || savingProgress >= 0 || card.closest(".overview-packed-grid") || !card.closest(".fixed-character-cards") || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
        const rect = card.getBoundingClientRect();
        const px = Math.max(0, Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width)));
        const py = Math.max(0, Math.min(1, (event.clientY - rect.top) / Math.max(1, rect.height)));
        card.style.setProperty("--card-tilt-x", `${(0.5 - py) * 14}deg`);
        card.style.setProperty("--card-tilt-y", `${(px - 0.5) * 14}deg`);
      } : undefined}
      onPointerLeave={characterInfo ? (event) => {
        event.currentTarget.style.setProperty("--card-tilt-x", "0deg");
        event.currentTarget.style.setProperty("--card-tilt-y", "0deg");
      } : undefined}
      onPointerCancel={characterInfo ? (event) => {
        event.currentTarget.style.setProperty("--card-tilt-x", "0deg");
        event.currentTarget.style.setProperty("--card-tilt-y", "0deg");
      } : undefined}
      onClick={(e) => {
        if (savingProgress >= 0) {
          e.preventDefault();
          e.stopPropagation();
          return;
        }
        if (e.shiftKey) {
          onToggle(asset.id);
          return;
        }
        if (characterInfo && !componentView && !asset.id.includes("::part::") && !e.currentTarget.closest(".overview-packed-grid")) {
          e.currentTarget.classList.remove("character-click-feedback");
          void e.currentTarget.offsetWidth;
          e.currentTarget.classList.add("character-click-feedback");
        }
        onSelect(asset.id);
      }}
      onContextMenu={(event) => {
        if (savingProgress >= 0) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onContextMenu(event, asset.id);
      }}
    >
      {!componentMeshSlots && <button
        className={`card-fav-btn ${isFavorite ? "active" : ""}`}
        disabled={savingProgress >= 0 || Boolean(componentView)}
        title={componentView ? (uiLanguage === "en" ? "Favorite the owner to keep its parts together" : "请收藏主体，部件随主体一起展示") : undefined}
        onClick={(e) => {
          e.stopPropagation();
          onToggleFavorite(asset.id);
        }}
      >
        <Icon name={isFavorite ? "heart-filled" : "heart"} />
      </button>}
      {!componentMeshSlots && !isFolderOnlyAsset(asset) && <button
        className={`card-export-btn ${exportDimmed ? "dimmed" : ""} ${actionLoading ? "loading" : ""}`}
        disabled={exportDisabled || savingProgress >= 0 || Boolean(componentView)}
        title={exportTitle || (uiLanguage === "en" ? `Send to ${cardTargetName}` : `发送到 ${cardTargetName}`)}
        onClick={(e) => {
          e.stopPropagation();
          onQuickExport(asset.id);
        }}
      >
        {actionLoading ? (
          <span className="card-export-progress" style={{ ["--export-progress" as string]: `${Math.max(0, Math.min(100, exportProgress))}%` }}>
            <Icon name="arrow-right" />
          </span>
        ) : (
          <Icon name={isFolderOnlyAsset(asset) ? "folder" : "arrow-right"} />
        )}
      </button>}
      <div
        className={`thumb ${String(asset.assetType || "").trim().toLowerCase() === "hdri" ? "thumb-hdri" : ""}${String(asset.assetType || "").trim().toLowerCase() === "animation" ? " thumb-animation" : ""}${componentMeshSlots ? " character-component-mesh-grid" : ""}`}
        style={componentMeshSlots ? { gridTemplateRows: componentView?.visibleMeshKind ? "minmax(0, 1fr)" : "repeat(2, minmax(0, 1fr))" } : String(asset.assetType || "").trim().toLowerCase() === "hdri" ? { padding: 0 } : undefined}
      >
        {componentMeshSlots ? (["staticMesh", "skeletalMesh"] as const).filter(kind => !componentView?.visibleMeshKind || kind === componentView.visibleMeshKind).map(kind => {
          const slot = componentMeshSlots[kind];
          const slotPath = String(slot?.previewPath || "");
          const slotLabel = kind === "staticMesh" ? "SM" : "SK";
          const slotTitle = kind === "staticMesh" ? "Static Mesh" : "Skeletal Mesh";
          const slotAssetName = /^(?:SM|SK)_/i.test(cardAssetName)
            ? cardAssetName.replace(/^(?:SM|SK)_/i, `${slotLabel}_`)
            : `${slotLabel}_${cardAssetName}`;
          const meshSelected = isSelected && kind === (selectedMeshKind || componentView?.visibleMeshKind || 'staticMesh');
          return <div key={kind} data-mesh-kind={slotLabel} role="button" tabIndex={0} aria-pressed={meshSelected} aria-label={`${slotTitle} · ${slotAssetName}`} className={`character-component-mesh-card${slot?.hasModel ? " populated" : " empty"}${meshSelected ? " mesh-selected" : ""}`} title={`${slotTitle} · ${slotAssetName}`}
            onClick={event => { event.stopPropagation(); if (savingProgress >= 0) return; if (event.shiftKey) onToggle(asset.id); else onSelect(asset.id, kind); }}
            onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); event.stopPropagation(); if (savingProgress < 0) onSelect(asset.id, kind); } }}>
            <div className="character-component-mesh-slot">
              <span className="character-component-mesh-tag">{slotLabel}</span>
              {kind === 'staticMesh' && slot?.hasModel && (componentView?.missingTextures || slot.previewState === 'stale') && <span className="character-component-texture-state">{componentView?.missingTextures ? (uiLanguage === 'en' ? 'Missing textures' : '缺少贴图') : previewWorkState === 'failed' ? (uiLanguage === 'en' ? 'Preview failed' : '预览失败·可重试') : previewWorkState === 'running' ? (uiLanguage === 'en' ? 'Generating preview' : '正在生成预览') : (uiLanguage === 'en' ? 'Preview queued' : '等待生成预览')}</span>}
              {kind === 'staticMesh' && characterRigProgress(asset).needsAttention && <span className="character-model-rig-dot" title={uiLanguage === 'en' ? 'Model changed: review rigging' : '模型已更新，请查看绑定提醒'} />}
              {slotPath ? <img className="loaded character-component-mesh-preview" src={getPreviewUrl(slotPath)} alt={`${slotAssetName} ${slotTitle}`} draggable={false} />
                : <div className="character-component-slot-empty">{slot?.hasModel ? (uiLanguage === "en" ? "Preview pending" : "预览待生成") : kind === "skeletalMesh" ? (uiLanguage === "en" ? "Skeletal model not uploaded" : "尚未上传骨骼模型") : (uiLanguage === "en" ? "Static model not uploaded" : "尚未上传静态模型")}</div>}
            </div>
            <div className="character-component-mesh-name" title={slotAssetName}>{slotAssetName}</div>
          </div>;
        }) : previewReloading ? <div className="character-preview-reloading">reloading</div> : <AssetThumbnail
          key={`${thumbnailSource}:${sourcePath}`}
          sourcePath={thumbnailSource}
          originalPath={failedLegacyCover ? "" : sourcePath}
          loader={previewLoader}
          toUrl={getPreviewUrl}
          name={cardAssetName}
          cover={String(asset.assetType || "").trim().toLowerCase() === "hdri"}
          onOriginalError={asset.assetType === "animation" && isAnimatedPreviewPath(sourcePath)
            ? () => setFailedAnimationCover(sourcePath) : undefined}
          fallback={<div style={{ opacity: 0.7 }}><Icon name="image-preview" /></div>}
        />}
        {(cardAnimationLabels.length > 0 || cardAnimationGameTag) && <div className="animation-labels animation-card-labels">
          {cardAnimationGameTag && <span className="animation-game-tag" title={cardAnimationGameTag.id}>{cardAnimationGameTag.name}</span>}
          {cardAnimationLabels.map(label => <span key={label}>{label}</span>)}
        </div>}
        {asset.assetType === 'animation' && <AnimationSendBadge asset={asset} language={uiLanguage} projectPath={animationProjectPath} />}
      </div>
      {characterInfo && !componentView && characterRigProgress(asset).needsAttention && <span className="character-model-rig-dot character-owner-rig-dot" title={uiLanguage === 'en' ? 'Rigging needs attention' : '请查看绑定提醒'} />}
      {!componentView && (cardWeapons.length > 0 || cardVariant) && <div className="monster-card-inventory">
        {cardVariant && <span className="monster-card-variant" title={cardVariant}>{uiLanguage === 'en' ? 'Variant: ' : '变体：'}{cardVariant}</span>}
        {cardWeapons.length > 0 && <span title={cardWeapons.map(item => item.name).join('、')}>
          {uiLanguage === 'en' ? `Weapons (${cardWeapons.length}): ` : `配套武器 ${cardWeapons.length} 件：`}{cardWeapons.map(item => item.name).join('、')}
        </span>}
      </div>}
      {characterInfo && !componentView && <span className="character-card-family" style={{ '--character-name-length': Math.max(1, Array.from(characterChineseName).length) } as CSSProperties}>{!heroPart && <span className="character-card-chinese-name">{characterChineseName}</span>}<span className={`character-card-status status-${characterStatus(characterInfo.maturity).value}`} lang={uiLanguage === "en" ? "en" : "zh"}>{characterStatus(characterInfo.maturity)[uiLanguage === "en" ? "en" : "zh"]}</span></span>}
      {characterInfo && !componentMeshSlots ? (
        <div className="character-card-summary">
          <div className={`character-card-caption${characterInfo.family === "monster" && !componentView ? " monster-card-caption" : ""}`}>
            {characterInfo.family === "monster" && !componentView && !characterInfo.fields.monsterVariantOnly && <span className="monster-card-form" title={uiLanguage === "en" ? "Current form / total forms" : "当前形态 / 总形态数"}>{monsterFormCounter}</span>}
            <div className="character-card-name" title={cardAssetName}>{cardAssetName}</div>
            {characterInfo.family === "monster" && !componentView && characterInfo.category && <span className="character-card-category">{getCharacterCategoryDisplayLabel("monster", characterInfo.category, uiLanguage)}</span>}
            {outfitClassLabel && !componentView && <span className="character-card-category">{outfitClassLabel}</span>}
            {heroPartLabel && !componentView && <span className="character-card-category">{heroPartLabel}</span>}
          </div>
        </div>
      ) : !characterInfo && asset.assetType !== 'animation' ? <div className="name">{cardAssetName}</div> : null}
      {savingProgress >= 0 && (
        <div
          className={`card-saving-mask ${saveComplete ? "complete" : ""}`}
          role="progressbar"
          aria-label={saveLabel}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={savePercent}
          aria-valuetext={`${saveLabel} ${savePercent}%`}
        >
          <div className="card-saving-panel">
            <div className="card-saving-status">
              <span className="card-saving-label">{saveComplete && <i aria-hidden="true" />}{saveLabel}</span>
              <span className="card-saving-value">{savePercent}%</span>
            </div>
            <div className="card-saving-track" aria-hidden="true">
              <span className="card-saving-progress" style={{ width: `${savePercent}%` }} />
            </div>
          </div>
        </div>
      )}
    </article>
  );
});

function OverviewAssetGrid({ assets, maxRows, children, fixedCharacters = false, viewport, previewLoader }: {
  assets: AssetRecord[];
  maxRows?: number;
  fixedCharacters?: boolean;
  viewport?: AssetStageMetrics;
  previewLoader?: PreviewLoader;
  children: (item: AssetGridItemLayout) => ReactNode;
}) {
  const ref = useRef<HTMLElement>(null);
  const [{ width, top }, setBounds] = useState({ width: 0, top: 0 });
  const virtual = Boolean(viewport);
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    const stage = virtual ? node.closest<HTMLElement>(".asset-stage") : null;
    const update = () => {
      const width = node.clientWidth;
      if (width <= 0) return;
      const top = stage ? node.getBoundingClientRect().top - stage.getBoundingClientRect().top + stage.scrollTop : 0;
      setBounds(previous => previous.width === width && previous.top === top ? previous : { width, top });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(node);
    if (stage && node.parentElement) observer.observe(node.parentElement);
    return () => observer.disconnect();
  }, [virtual]);
  const layout = useMemo(() => buildAssetGridLayout(width ? assets : [], width, false, 0, false, fixedCharacters, fixedCharacters ? 240 : undefined), [assets, width, fixedCharacters]);
  const height = maxRows === undefined ? layout.totalHeight : Math.max(0, Math.min(layout.totalHeight, maxRows * (layout.cardHeight + layout.gap) - layout.gap));
  const viewportHeight = viewport?.viewportHeight ?? 0;
  const scrollTop = (viewport?.scrollTop ?? 0) - top;
  const items = virtual ? getVisibleAssetGridItems(layout.items, viewportHeight, scrollTop, layout.cardHeight) : layout.items.filter(item => item.y < height);
  useLayoutEffect(() => {
    if (!virtual || !previewLoader) return;
    previewLoader.setViewport(getAssetGridItemsInRange(layout.items, scrollTop, scrollTop + viewportHeight)
      .map(item => getAssetThumbnailSource(item.asset)));
  }, [virtual, previewLoader, layout.items, scrollTop, viewportHeight]);
  return (
    <section ref={ref} className="asset-grid asset-grid-virtual overview-packed-grid" style={{ height, minHeight: 0 }}>
      {width > 0 && items.map(children)}
    </section>
  );
}

function LibraryCategoryOverview({ category, data, loader, t, scanning, labelFor, onOpenCategory, viewport, renderAsset }: {
  category: LibraryCategory;
  data: ReturnType<typeof buildLibraryCategoryOverview>;
  loader: PreviewLoader;
  t: (zh: string, en: string) => string;
  scanning: boolean;
  labelFor: (id: string, fallback: string) => string;
  onOpenCategory: (id: string) => void;
  viewport: AssetStageMetrics;
  renderAsset: (item: AssetGridItemLayout) => ReactNode;
}) {
  const [seed] = useState(() => Math.floor(Math.random() * 2 ** 32));
  const ordered = useMemo(() => buildStaggeredOrder(data.assets, seed), [data.assets, seed]);

  return (
    <div className={`all-overview-wrapper library-category-overview library-category-overview-${category}`}>
      <section className="overview-section">
        <h2 className="overview-section-title">{labelFor(category, category)}</h2>
        <div className="library-category-tiles">
          {data.sections.map(({ id, label, cover }) => (
            <button key={id} type="button" className="library-category-tile" onClick={() => onOpenCategory(id)}>
              <span className="library-category-art" aria-hidden="true">
                <AssetThumbnail key={cover} sourcePath={cover} loader={loader} toUrl={getPreviewUrl}
                  name="" cover={false} fallback={<Icon name={category === "environment" ? "cube" : "file"} />} />
              </span>
              <span className="library-category-caption">{labelFor(id, label)}</span>
            </button>
          ))}
        </div>
      </section>
      {ordered.length > 0 ? (
        <OverviewAssetGrid assets={ordered} viewport={viewport} previewLoader={loader} fixedCharacters={category === "character"}>{renderAsset}</OverviewAssetGrid>
      ) : (
        <p className="overview-empty-hint">{scanning ? t("正在扫描资产…", "Scanning assets…") : t("该分类暂无资产", "No assets in this category")}</p>
      )}
    </div>
  );
}

function hashForStagger(input: string, seed: number) {
  let hash = seed ^ 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function buildStaggeredOrder(list: AssetRecord[], seed: number) {
  if (!Array.isArray(list) || list.length <= 2) {
    return list;
  }
  const withKeys = list.map(item => ({
    item,
    key: hashForStagger(String(item.id), seed)
  }));
  const sorted = withKeys.sort((a, b) => {
    if (a.key !== b.key) {
      return a.key - b.key;
    }
    return String(a.item.id).localeCompare(String(b.item.id));
  }).map(w => w.item);
  return sorted;
}

type DarkSelectOption = {
  value: string;
  label: string;
  checked?: boolean;
  labelContent?: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
};

const EXPORT_TARGET_OPTIONS: DarkSelectOption[] = [
  { value: "unreal", label: "Unreal Engine" },
  { value: "blender", label: "Blender" },
  { value: "3dcoat", label: "3DCoat" }
];

const SETTINGS_EXPORT_TARGET_OPTIONS: DarkSelectOption[] = EXPORT_TARGET_OPTIONS.map(option => ({
  ...option,
  icon: <Icon name={option.value} />,
  labelContent: <span className="export-target-brand-name">
    <img className={`export-target-wordmark export-target-wordmark-${option.value}`}
      src={option.value === "blender" ? blenderWordmark : option.value === "3dcoat" ? threeDCoatWordmark : unrealWordmark}
      alt="" aria-hidden="true" />
    <span className="export-target-accessible-name">{option.label}</span>
  </span>
}));

// 导入重复检测暂时停用；保留单资产和批量策略代码，之后可重新启用。
const importDuplicateCheckEnabled = false;

// 导入界面内联展示的重复资产检测结果：导入前就告知是否重复，并由用户选择处理方式。
type ImportDedupeState = {
  signature: string;
  status: "checking" | "ready" | "error";
  duplicate: boolean;
  matchKind?: "identical" | "source" | "content" | "name";
  candidateName: string;
  candidateId?: string;
  defaultAction: "skip" | "update" | "new";
  decision?: "skip" | "update" | "new";
  contentIdentity?: {
    fingerprintVersion?: string;
    contentFingerprint: string;
    modelFingerprints?: Record<string, string>;
    textureFingerprint?: string;
  };
  message: string;
};

const DarkSelect = memo(({
  value,
  mixed = false,
  options,
  onChange,
  confirmSameValue = false,
  disabled = false,
  lockOpen = false,
  hideChevron = false,
  triggerContent,
  className = "",
  menuClassName = "",
  itemClassName = "",
  ariaLabel,
  title,
  invalid = false,
  searchPlaceholder,
  emptySearchLabel
}: {
  value: string;
  mixed?: boolean;
  options: DarkSelectOption[];
  onChange: (nextValue: string) => void;
  confirmSameValue?: boolean;
  disabled?: boolean;
  lockOpen?: boolean;
  hideChevron?: boolean;
  triggerContent?: ReactNode;
  className?: string;
  menuClassName?: string;
  itemClassName?: string;
  ariaLabel: string;
  title?: string;
  invalid?: boolean;
  searchPlaceholder?: string;
  emptySearchLabel?: string;
}) => {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const rootRef = useRef<HTMLDivElement | null>(null);
  const activeOption = options.find((option) => option.value === value) || options[0];
  const multiSelect = options.some(option => option.checked !== undefined);
  const filteredOptions = searchPlaceholder && query.trim()
    ? options.filter(option => `${option.label} ${option.value}`.toLowerCase().includes(query.trim().toLowerCase()))
    : options;

  useEffect(() => {
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current) {
        return;
      }
      if (!rootRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
      }
    };
    window.addEventListener("mousedown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("mousedown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, []);

  return (
    <div className={`dark-select ${className}`.trim()} ref={rootRef}>
      <button
        type="button"
        className={`dark-select-trigger${hideChevron ? " no-chevron" : ""}`}
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={ariaLabel}
        aria-invalid={invalid || undefined}
        title={title ?? (triggerContent ? `${ariaLabel}: ${activeOption?.label || value}` : undefined)}
        onClick={() => {
          if (disabled || lockOpen) {
            return;
          }
          setOpen((prev) => !prev);
          setQuery("");
        }}
      >
        <span>{mixed ? "Multiple Value" : triggerContent ?? <>{activeOption?.icon}{activeOption?.labelContent ?? (activeOption?.label || value)}</>}</span>
      </button>
      {open && !lockOpen && (
        <div className={`dark-select-menu ${menuClassName}`.trim()}>
          {searchPlaceholder && <input className="dark-select-search" autoFocus value={query} placeholder={searchPlaceholder}
            aria-label={searchPlaceholder} onChange={event => setQuery(event.target.value)} />}
          <div role="listbox" aria-multiselectable={multiSelect || undefined} aria-label={ariaLabel}>
          {filteredOptions.map((option) => (
            <button
              key={option.value}
              type="button"
              role="option"
              disabled={disabled || option.disabled}
              aria-selected={option.checked ?? (!mixed && option.value === (activeOption?.value || value))}
              className={`dark-select-item ${itemClassName} ${(option.checked ?? (!mixed && option.value === (activeOption?.value || value))) ? "active" : ""}`.trim()}
              onClick={() => {
                if (!multiSelect) setOpen(false);
                if (option.disabled || (!multiSelect && !confirmSameValue && !mixed && option.value === value)) {
                  return;
                }
                onChange(option.value);
              }}
            >
              {multiSelect && <span aria-hidden="true">{option.checked ? "☑" : "☐"} </span>}
              {option.icon}{option.labelContent ?? option.label}
            </button>
          ))}
          {!filteredOptions.length && <div className="dark-select-empty" role="status">{emptySearchLabel}</div>}
          </div>
        </div>
      )}
    </div>
  );
});



function monsterFormLabel(asset: AssetRecord, language: string) {
  const ids = (asset.meta?.character as Partial<CharacterImportFields> | undefined)?.formIds || [];
  const label = ids.map(id => id === 'base' ? (language === 'en' ? 'Base' : '基础') : id).join(' / ');
  return label ? (language === 'en' ? 'Form ' : '形态 ') + label : (language === 'en' ? 'Form unspecified' : '形态未标记');
}

const RelatedAssetCard = ({ asset, onSelect, caption }: { asset: AssetRecord; onSelect: (assetId: string) => void; caption?: string }) => {
  const [fitScaled, setFitScaled] = useState(false);
  return (
    <button key={asset.id} className={`related-card${caption ? ' related-form-card' : ''}`} title={characterDisplayName(asset)} onClick={() => onSelect(asset.id)}>
      {(asset.previewImage || asset.preview) ? (
        isMotionVideoPreviewPath(String(asset.previewImage || asset.preview || "")) ? (
          <AnimationPreviewVideo
            src={getPreviewUrl(asset.previewImage || asset.preview)}
            className={fitScaled ? "fit-scaled" : ""}
            onLoadedMetadata={(event) => {
              const video = event.currentTarget;
              const ratio = video.videoWidth > 0 && video.videoHeight > 0 ? video.videoWidth / video.videoHeight : 1;
              setFitScaled(Math.abs(ratio - 1) > 0.04);
            }}
          />
        ) : (
        <img
          src={getPreviewUrl(asset.previewImage || asset.preview)}
          alt={characterDisplayName(asset)}
          className={fitScaled ? "fit-scaled" : ""}
          onLoad={(event) => {
            const img = event.currentTarget;
            const ratio = img.naturalWidth > 0 && img.naturalHeight > 0 ? img.naturalWidth / img.naturalHeight : 1;
            setFitScaled(Math.abs(ratio - 1) > 0.04);
          }}
        />
        )
      ) : (
        <span>{asset.name}</span>
      )}
      {caption && <span className="related-form-caption">{caption}</span>}
    </button>
  );
};

function normalizeThemeToken(input: string) {
  return input.trim().toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ");
}

