type CharacterUpdateMode = "whole" | "selective";
function characterImportLodFiles(form: ImportFormState) {
  const fields = form.characterFields;
  const owner = buildCharacterAssetName(form.assetType, fields, form.subCategory);
  const aliases = form.assetType === 'monster' ? auditMonsterPackage(form.characterPackageFiles, { expectedName: fields.name, modelAnalyses: form.characterModelAnalysis }).modelAliases : undefined;
  return form.characterPackageFiles.filter(file => /\.fbx$/i.test(file)).map(file => {
    const analysis = form.characterModelAnalysis[file];
    const kind = analysis?.meshKind || 'staticMesh';
    const index = Number(file.match(/_LOD(\d+)(?=\.[^.]+$)/i)?.[1] || 0);
    const name = form.assetType === 'suit'
      ? heroModelStem(owner, file, fields, kind) + (index ? `_LOD${index}` : '') + '.fbx'
      : previewFamilyFileName(form.assetType, owner, file, fields.name, aliases).replace(/^(SK|SM)_/i, kind === 'skeletalMesh' ? 'SK_' : 'SM_');
    return { name, sourcePath: file, sourceHash: analysis?.sourceHash, kind,
      inspection: !analysis ? 'pending' as const : analysis.ok ? 'ready' as const : 'failed' as const, inspectionMessage: analysis?.message };
  });
}

function characterImportLodsConfirmed(form: ImportFormState) {
  const files = characterImportLodFiles(form);
  return !files.length || form.characterLodConfirmation === characterLodReviewToken(files);
}
type CharacterUpdateModelRole = "staticMesh" | "skeletalMesh";
type CharacterUpdateSection = CharacterUpdateModelRole | "texture" | "lod";
type CharacterUpdateDestination = { storedPath: string; fileName: string; role: CharacterUpdateModelRole | "texture"; isNew?: boolean; lod?: number; modelName?: string };
type CharacterUpdateBatchReport = { unmatchedFiles: string[]; conflictFiles: Array<{ storedPath: string; sourcePaths: string[] }>; excludedFiles: string[] };
type CharacterUpdateInputRow = { sourcePath: string; role: string; storedPath: string; candidates: Array<{ storedPath: string; name: string }> };

function characterUpdateDestinations(asset: AssetRecord | null): CharacterUpdateDestination[] {
  if (!asset) return [];
  const destinations: CharacterUpdateDestination[] = activeCharacterFiles(asset).flatMap(file => {
    const role: CharacterUpdateDestination['role'] | "" = file.role === "skeletalMesh" ? "skeletalMesh"
      : ["model", "staticMesh"].includes(file.role) ? "staticMesh"
      : file.role === "texture" ? "texture" : "";
    const fileName = file.normalizedName || characterFileBaseName(file.storedPath);
    const lod = role !== 'texture' ? Number(fileName.match(/_LOD(\d+)(?=\.[^.]+$)/i)?.[1] || 0) : 0;
    return role && !lod ? [{ storedPath: file.storedPath, fileName, role }] : [];
  });
  if (asset.meta.componentView) {
    for (const role of ["staticMesh", "skeletalMesh"] as const) if (!destinations.some(item => item.role === role)) {
      destinations.push({ storedPath: `__new_character_mesh__:${role}`, fileName: role === "staticMesh" ? "新增静态模型" : "新增骨骼模型", role, isNew: true });
    }
  } else if (isCharacterAssetType(asset.assetType)) {
    for (const part of characterModelUpdateGroups(asset)) {
      for (const role of ["staticMesh", "skeletalMesh"] as const) if (!part.meshKinds?.[role]) {
        destinations.push({ storedPath: `__new_character_mesh__:${role}:${encodeURIComponent(part.slot)}`,
          fileName: `${role === "staticMesh" ? "新增静态模型" : "新增骨骼模型"} · ${part.label || part.name}`, role, isNew: true });
      }
    }
  }
  return [...destinations, ...characterLodUpdateTargets(characterModelUpdateGroups(asset))];
}

function previewViewTag(tags: string[] | undefined) {
  return (tags || []).find(tag => tag.startsWith("view:"))?.slice(5) || "";
}

function characterImageIsReloading(asset: AssetRecord, tags?: string[]) {
  const component = asset.meta.componentView as { slot?: string } | undefined;
  const state = asset.meta.characterComponents as { slots?: Record<string, { previewReloading?: boolean }>; autoPreviewPendingViews?: string[] } | undefined;
  if (component?.slot) return state?.slots?.[component.slot]?.previewReloading === true;
  const view = previewViewTag(tags);
  return Boolean(view && state?.autoPreviewPendingViews?.includes(view) && !(tags || []).includes("origin:manual"));
}

function characterHistoryDisplayEntries(asset: AssetRecord): CharacterHistoryDisplayEntry[] {
  const raw = Array.isArray(asset.meta.characterUpdateHistory)
    ? asset.meta.characterUpdateHistory as Array<{ id?: string; at?: string; label?: string; note?: string; sourcePaths?: string[]; changes?: Array<{ name?: string; status?: string; before?: string; after?: string }>; files?: Array<{ name?: string; previousName?: string; status?: string; sourcePath?: string; sourceIndex?: number; uePath?: string; message?: string }> }>
    : [];
  if (raw.length) return raw.map((entry, entryIndex) => {
    const sources = Array.isArray(entry.sourcePaths) ? entry.sourcePaths : [];
    const changes = Array.isArray(entry.changes) ? entry.changes : [];
    const files: CharacterHistoryDisplayFile[] = Array.isArray(entry.files) && entry.files.length
      ? entry.files.map((file, index) => ({ name: String(file.name || ""), previousName: String(file.previousName || ""), status: String(file.status || "changed"), sourcePath: String(file.sourcePath || ""), sourceIndex: file.uePath ? -1 : Number.isInteger(file.sourceIndex) ? Number(file.sourceIndex) : index, uePath: file.uePath, message: file.message }))
      : sources.map((sourcePath, index) => {
        const name = characterFileBaseName(sourcePath);
        const change = changes.find(item => String(item.name || "").toLowerCase() === name.toLowerCase()) || changes[index];
        return { name: String(change?.name || name), status: String(change?.status || "changed"), sourcePath, sourceIndex: index };
      });
    const represented = new Set(files.map(file => file.name.toLowerCase()));
    for (const change of changes) {
      const name = String(change.name || "");
      if (!name || represented.has(name.toLowerCase()) || change.status === "retained") continue;
      files.push({ name, before: String(change.before || ""), after: String(change.after || ""), status: String(change.status || "changed"), sourcePath: "", sourceIndex: -1 });
    }
    return { id: String(entry.id || `history-${entryIndex}`), at: String(entry.at || asset.meta.updatedAt || asset.createdAt || ""), label: characterHistorySummary(entry), note: entry.label === '发送到 UE' ? '' : String(entry.note || ""), automaticPreview: /四视图更新|自动.*预览/.test(entry.label || ''), legacy: false, files, projectPath: (entry as { details?: { projectPath?: string } }).details?.projectPath };
  });
  const manifest = asset.meta.characterManifest as { contentUpdatedAt?: string; confirmedAt?: string; files?: Array<{ normalizedName?: string; originalName?: string; originalPath?: string; sourcePath?: string; role?: string }> } | undefined;
  return [{
    id: "legacy-current",
    at: String(manifest?.contentUpdatedAt || manifest?.confirmedAt || asset.meta.updatedAt || asset.createdAt || ""),
    label: "当前版本（历史功能启用前入库）",
    note: "",
    legacy: true,
    files: (manifest?.files || []).map((file, sourceIndex) => ({ name: String(file.normalizedName || file.originalName || ""), status: "current", sourcePath: String(file.originalPath || file.sourcePath || ""), sourceIndex })).filter(file => file.name)
  }];
}

// 标签比较键：忽略大小写、空格、下划线、连字符，因此 "Flowering Plant"、
// "flowering_plant" 与 "floweringplant" 视为同一个词。
function normalizeTagKey(value: unknown) {
  return String(value ?? "").trim().toLowerCase().replace(/[\s_-]+/gu, "");
}

// Asset Type 与「分类」属于分类维度，不作为普通标签生成：导入草稿与编辑弹窗的
// 「标签」槽只保留真正的标签，详情页的 tag 区域仍按分类自动展示。与分类同名的
// 标准 Asset Tag（如 3D Assets 的 Props）必须保留，否则会丢掉
// 资产真正的标准标签。
function buildTaxonomyTagKeys(input: {
  assetType?: unknown;
  assetTypeLabel?: unknown;
  subCategory?: unknown;
  category?: unknown;
  folderAliases?: Array<string | null | undefined>;
  keepTags?: Array<string | null | undefined>;
}) {
  const keep = new Set((input.keepTags || []).map((tag) => normalizeTagKey(tag)).filter(Boolean));
  const keys = new Set<string>();
  const add = (value: unknown) => {
    const key = normalizeTagKey(value);
    if (key && !keep.has(key)) {
      keys.add(key);
    }
  };
  add(input.assetType);
  add(input.assetTypeLabel);
  for (const alias of input.folderAliases || []) {
    add(alias);
  }
  add(input.subCategory);
  add(input.category);
  return keys;
}

function isTaxonomyTag(tag: unknown, taxonomyTagKeys: Set<string>) {
  return taxonomyTagKeys.has(normalizeTagKey(tag));
}

function CharacterAdvancedConfiguration({ enabled, children }: { enabled: boolean; children: ReactNode }) {
  return enabled ? <details className="character-import-advanced"><summary>高级配置 · 模型与贴图（可选）</summary>{children}</details> : <>{children}</>;
}

