  // 因此全部资产完成之前任务栏绝不会显示满格。
  // 此前任务栏用的是 (position+1)/total —— 单资产导入从第一秒起就是 100%，
  // "看着已经完成"，与关闭时"还有资产在导入"的提示自相矛盾。
  const importTaskbarBaseRef = useRef(0);
  const importTaskbarSpanRef = useRef(1);
  const prequeueEditingRef = useRef(false);
  useEffect(() => { prequeueEditingRef.current = prequeueEditing; }, [prequeueEditing]);
  const [batchImportProgress, setBatchImportProgress] = useState<{ processed: number; total: number; active: boolean } | null>(null);
  const batchImportProgressClearTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => {
    if (batchImportProgressClearTimerRef.current) clearTimeout(batchImportProgressClearTimerRef.current);
  }, []);
  // 后台导入期间拖入的资产先暂存于此，待当前批次结束后追加进待导入列表，
  // 避免与导入循环里的草稿快照（remaining）互相覆盖产生竞态。
  const pendingImportAppendsRef = useRef<Array<{ form: ImportFormState; tagInput: string }>>([]);
  const activeBatchDraftsRef = useRef<Array<{ form: ImportFormState; tagInput: string }>>([]);
  const singleDraftQueueIdRef = useRef(crypto.randomUUID());
  const [importSidebarCollapsed, setImportSidebarCollapsed] = useState(true);

  // 批量导入列表排序：先按资产类型分组（同类型相邻），类型内再按名称排序。
  // 返回排序后的「原始索引」顺序，供显示与 Shift 连续选择使用。
  const sortedImportIndexes = useMemo(() => {
    const typeOrder = ["3d", "3dplant", "surface", "decal", "atlas", "imperfection", "displacement", "hdri"];
    const rank = (type: string) => {
      const key = String(type || "").trim().toLowerCase();
      const pos = typeOrder.indexOf(key);
      return pos === -1 ? typeOrder.length : pos;
    };
    const drafts = importDrafts.length ? importDrafts : [{ form: importForm }];
    return drafts
      .map((draft, index) => {
        const form = index === activeImportIndex ? importForm : draft.form;
        return {
          index,
          type: String(form.assetType || "").trim().toLowerCase(),
          name: String(form.assetName || "").trim()
        };
      })
      .sort((a, b) => {
        const typeCmp = rank(a.type) - rank(b.type);
        if (typeCmp !== 0) return typeCmp;
        const typeNameCmp = a.type.localeCompare(b.type);
        if (typeNameCmp !== 0) return typeNameCmp;
        return a.name.localeCompare(b.name, "zh-Hans-CN", { numeric: true, sensitivity: "base" });
      })
      .map((entry) => entry.index);
  }, [importDrafts, importForm, activeImportIndex]);
