  const revealedCharacterCardRef = useRef("");
  useEffect(() => {
    if (!selectedAssetId || !["monster", "suit"].includes(selectedAsset?.assetType || "")) {
      revealedCharacterCardRef.current = "";
      return;
    }
    const item = assetGridLayout.items.find(item => item.asset.id === selectedAssetId && (item.variantId === undefined || item.variantId === selectedMonsterVariant));
    const stage = assetStageRef.current;
    if (!item || !stage) return;
    // Scanning/preview renders must not restart an unchanged smooth-scroll target.
    const revealKey = `${selectedAssetId}:${item.x}:${item.y}:${item.width}:${item.height}`;
    if (revealedCharacterCardRef.current === revealKey) return;
    revealedCharacterCardRef.current = revealKey;
    if (item.y < stage.scrollTop || item.y + item.height > stage.scrollTop + stage.clientHeight) stage.scrollTo({ top: Math.max(0, item.y - 24), behavior: "smooth" });
    const frame = requestAnimationFrame(() => {
      const card = document.getElementById(`asset-card-${monsterCardOccurrence(selectedAssetId, item.variantId)}`);
      const row = card?.closest<HTMLElement>(".character-showcase-row");
      if (row && (item.x < row.scrollLeft || item.x + item.width > row.scrollLeft + row.clientWidth)) {
        row.scrollTo({ left: Math.max(0, item.x - 12), behavior: "smooth" });
      }
    });
    return () => cancelAnimationFrame(frame);
  }, [selectedAssetId, selectedAsset?.assetType, assetGridLayout.items, selectedMonsterVariant]);

  const keyboardCardRef = useRef<HTMLElement | null>(null);
  function handleAssetStageKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || event.isPropagationStopped()) return;
    if (!["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.key)) return;
    const target = event.target as HTMLElement;
    if (target.closest("input, textarea, select, button, a, [contenteditable]:not([contenteditable='false']), [role='combobox'], [role='slider']")) return;
    const stage = event.currentTarget;
    const direction = event.key as GridDirection;
    const stageRect = stage.getBoundingClientRect();
    const items = isOverviewView
      ? Array.from(stage.querySelectorAll<HTMLElement>(".asset-card")).map((element) => {
        const rect = element.getBoundingClientRect();
        return { id: element.dataset.assetId || element.id.slice("asset-card-".length), variantId: element.dataset.variantId, element, x: rect.left - stageRect.left, y: rect.top - stageRect.top + stage.scrollTop, width: rect.width, height: rect.height };
      })
      : packedAssetGrid.items.map((item) => ({ ...item, id: item.asset.id, element: null as HTMLElement | null }));
    // Remember the specific occurrence when an asset also appears in Recently used.
    const current = items.find((item) => item.id === selectedAssetId && (item.variantId === undefined ? item.element === keyboardCardRef.current : item.variantId === selectedMonsterVariant))
      || items.find((item) => item.id === selectedAssetId);
    if (!current) {
      if (direction === "ArrowUp" || direction === "ArrowDown") {
        event.preventDefault();
        stage.scrollBy({ top: direction === "ArrowUp" ? -80 : 80, behavior: "instant" });
      }
      return;
    }
    event.preventDefault();
    const next = getDirectionalGridItem(items, current, direction);
    if (!next) return;
    keyboardCardRef.current = next.element;
    if (next.variantId !== undefined) setMonsterVariantSelection({ assetId: next.id, variantId: next.variantId });
    handleSelectAsset(next.id);
    if (next.y < stage.scrollTop) stage.scrollTop = next.y;
    else if (next.y + next.height > stage.scrollTop + stage.clientHeight) {
      stage.scrollTop = next.y + next.height - stage.clientHeight;
    }
  }

  function runQuickAssetAction(assetId: string) {
    const asset = allAssets.find((item) => item.id === assetId);
    if (isFolderOnlyAsset(asset)) {
      if (bridgeAvailable && asset?.path) void bridge.openFolder(asset.path);
      return;
    }
    void runImport([assetId]);
  }

  // Preserve the callback identity while dispatching with current asset and export settings.
  const quickExportRef = useRef<(assetId: string) => void>(() => {});
  useEffect(() => {
    quickExportRef.current = runQuickAssetAction;
  });
  const handleQuickExport = useCallback((assetId: string) => quickExportRef.current(assetId), []);

  function toggleCategory(id: string) {
    if (id === "home") return;
    setExpandedCategories(prev => {
      // Selecting a different branch opens it; clicking the active branch toggles it.
      const isExpanding = activeMenu !== id || !prev.includes(id);
      if (["environment", "character", "animation"].includes(id)) {
        return isExpanding ? ["home", id] : ["home"];
      }

      // Known main categories
      const mainCategories = ["environment", "character", "animation", "3d-assets", "3d-plants", "surfaces", "decals", "atlases", "imperfections", "displacements", "hdri",
        "character-suit", "character-monster", "character-npc", "character-weapon", "character-item",
        "animation-hero", "animation-monster", "animation-npc",
        "fav-3d", "fav-3dplant", "fav-surface", "fav-decal", "fav-atlas", "fav-imperfection", "fav-displacement", "fav-hdri", "fav-animation"];

      if (isExpanding && mainCategories.includes(id)) {
        if (id.startsWith("fav-")) {
          return ["favorite", id];
        }
        if (["animation-hero", "animation-monster", "animation-npc"].includes(id)) {
          return ["home", "animation", id];
        }
        if (["character-suit", "character-monster", "character-npc", "character-weapon", "character-item"].includes(id)) {
          return ["home", "character", id];
        }
        if (["3d-assets", "3d-plants", "surfaces", "decals", "atlases", "imperfections", "displacements", "hdri"].includes(id)) {
          return ["home", "environment", id];
        }
        return ["home", id];
      }

      return isExpanding ? [...prev, id] : prev.filter(c => c !== id);
    });
  }

  function expandOutlineForCategory(categoryId: string) {
    if (categoryId === "animation") {
      setExpandedCategories(["home", "animation"]);
      return;
    }
    setExpandedCategories(["home", "environment", categoryId]);
  }

  const [suitExportAssetIds, setSuitExportAssetIds] = useState<string[] | null>(null);
  const [linkAssetIds, setLinkAssetIds] = useState<string[] | null>(null);
  const [connectedUeProjectPath, setConnectedUeProjectPath] = useState('');
  const [connectedUeProjectId, setConnectedUeProjectId] = useState('');
  const [suitExportHidden, setSuitExportHidden] = useState(false);
  const [suitExportBusy, setSuitExportBusy] = useState(false);
  const [suitExportSession, setSuitExportSession] = useState(0);
  const [refreshingUePath, setRefreshingUePath] = useState(false);
  async function refreshSelectedUePath() {
    if (!selectedAsset || refreshingUePath) return;
    const selectedId = selectedAsset.id;
    setRefreshingUePath(true);
    try {
      const reply = await bridge.getSuitUnrealStatus(componentParentId(selectedId));
      if (!reply.ok) throw new Error(reply.message || t('UE 正忙或未连接，请稍后重试', 'UE is busy or disconnected. Try again.'));
      await refreshAssetFromDisk(selectedId);
      showStatus(t('已从当前目标 UE 刷新资源状态', 'Resource status refreshed from the target UE project'), 4000);
    } catch (error) { showStatus(String(error), 10000); }
    finally { setRefreshingUePath(false); }
  }
  const [animationExportAssetIds, setAnimationExportAssetIds] = useState<string[] | null>(null);
  useEffect(() => {
    if (!bridgeAvailable || typeof bridge.getAnimationGameTagOptions !== "function") return;
    let disposed = false;
    bridge.getAnimationGameTagOptions().then((result) => {
      if (!disposed && result) setAnimationGameTagOptions({ weapons: result.weapons || [], monsters: result.monsters || [] });
    }).catch(() => {});
    return () => { disposed = true; };
  }, [bridge, bridgeAvailable, unrealConnected]);
  function renderAnimationGameTagSelect(affiliation: string, value: AnimationGameTag | null | undefined, mixed: boolean, onChange: (tag: AnimationGameTag | null) => void, required = false) {
    const kind = animationGameTagKind(affiliation);
    if (!kind) return null;
    const list = kind === "weapon" ? animationGameTagOptions.weapons : animationGameTagOptions.monsters;
    const current = value && value.kind === kind ? value : null;
    const options = current && !list.some(option => option.id === current.id) ? [{ ...current, group: "" }, ...list] : list;
    return (
      <div className="settings-row">
        <div className="settings-label">{kind === "weapon" ? t("武器类别", "Weapon Category") : t("怪物", "Monster")}{required && <span className="required-asterisk" aria-hidden="true">*</span>}</div>
        <div className="settings-field-col">
          <DarkSelect
            value={current?.id || ""}
            mixed={mixed}
            ariaLabel={kind === "weapon" ? t("武器类别", "Weapon Category") : t("怪物", "Monster")}
            className="settings-dark-select"
            searchPlaceholder={kind === "weapon" ? t("搜索武器名称或编号", "Search weapon name or ID") : t("搜索怪物名称或编号", "Search monster name or ID")}
            emptySearchLabel={t("没有匹配项", "No matches")}
            options={[
              { value: "", label: t("未指定", "Not set") },
              ...options.map(option => ({ value: option.id, label: formatAnimationGameTag(option) }))
            ]}
            onChange={(nextValue) => {
              const option = options.find(item => item.id === nextValue);
              onChange(option ? { kind: option.kind, id: option.id, name: option.name } : null);
            }}
          />
          <div className="settings-field-hint">{kind === "weapon" ? t("来自 UE DT_WeaponCategoryConfig，显示在动画上并可搜索", "From UE DT_WeaponCategoryConfig; shown on the animation and searchable") : t("来自 UE DT_MonsterPrototype，显示在动画上并可搜索", "From UE DT_MonsterPrototype; shown on the animation and searchable")}</div>
        </div>
      </div>
    );
  }
  const selectedSuitOwnerId = selectedAsset && ['suit', 'weapon', 'monster', 'npc', 'item'].includes(selectedAsset.assetType) ? componentParentId(selectedAsset.id) : '';
  useEffect(() => {
    if (!selectedSuitOwnerId || !unrealConnected || suitExportAssetIds || !bridge.getSuitUnrealStatus) return;
    let disposed = false;
    const check = async () => {
      try {
        const reply = await bridge.getSuitUnrealStatus(selectedSuitOwnerId);
        if (!disposed && reply.ok && reply.changed) await refreshAssetFromDisk(selectedAssetIdRef.current || selectedSuitOwnerId);
      } catch { /* Offline editors retain the last confirmed receipt. */ }
    };
    const stop = pollWindowStatus(check, 15000);
    return () => { disposed = true; stop(); };
  }, [selectedSuitOwnerId, unrealConnected, suitExportAssetIds, bridge, refreshAssetFromDisk]);
  async function runImport(assetIds: string[]) {
    if (savingOverwritePolicy && !isBlenderTarget && !isThreeDCoatTarget) return;
    if (suitExportAssetIds && suitExportBusy) {
      setSuitExportHidden(false);
      if (JSON.stringify([...new Set(assetIds.map(componentParentId))].sort()) !== JSON.stringify([...suitExportAssetIds].sort())) {
        showStatus(t('另一个资产的 UE 任务仍在运行，请等待该任务完成', 'Another asset is still processing in UE. Wait for it to finish.'), 6000);
      }
      return;
    }
    const suits = assetIds.filter(id => {
      const asset = allAssets.find(item => item.id === componentParentId(id));
      return ['weapon', 'monster', 'suit', 'npc', 'item'].includes(asset?.assetType || '');
    });
    if (assetIds.some(id => componentParentId(id) !== id) && (isBlenderTarget || isThreeDCoatTarget || suits.length !== assetIds.length)) { showStatus(t("此类型暂不支持部件独立导出", "This type does not support component export yet"), 8000); return; }
    if (busy || isExporting || pluginInstalling || exportInFlightRef.current) return;
    if (!bridgeAvailable) {
      showStatus(t("导出需要桌面端环境，请运行 npm run dev", "Export requires the desktop app. Run npm run dev"), 10000);
      return;
    }
    if (assetIds.length === 0) {
      showStatus(t("请先勾选资产", "Select assets first"), 2500);
      return;
    }
    const unavailableTitle = getAssetExportUnavailableTitle(assetIds);
    if (unavailableTitle) {
      showStatus(unavailableTitle, 10000);
      return;
    }
    if (!isBlenderTarget && !isThreeDCoatTarget && suits.length) {
      if (suits.length !== assetIds.length) { showStatus(t("请将套装与其他类型分批发送", "Send suits separately from other types"), 6000); return; }
      setSuitExportAssetIds([...new Set(assetIds.map(componentParentId))]);
      setSuitExportSession(current => current + 1);
      setSuitExportHidden(false);
      return;
    }
    const animationIds = assetIds.filter(id => String(allAssets.find(item => item.id === id)?.assetType || "").trim().toLowerCase() === "animation");
    if (!isBlenderTarget && !isThreeDCoatTarget && animationIds.length) {
      if (animationIds.length !== assetIds.length) { showStatus(t("请将动画与其他类型分批发送", "Send animations separately from other types"), 6000); return; }
      assetIds.forEach((id) => recordAssetUsage(id));
      setAnimationExportAssetIds([...new Set(assetIds)]);
      return;
    }
    assetIds.forEach((id) => recordAssetUsage(id));
    if (isThreeDCoatTarget) {
      // AppLink 一次接收一个模型；所有导出入口先经过同一套目标与资产检查。
      setThreeDCoatAssetId(assetIds[0]);
      return;
    }
    setImportingAssetIds(assetIds);
    exportInFlightRef.current = true;
    setIsExporting(true);
    setExportProgress(0);
    setExportStage(t("准备导入任务", "Preparing import"));
    showExportStatus(t(`正在导入 ${exportTargetName}...`, `Importing into ${exportTargetName}...`), 0);
    try {
      const exportAssets = isBlenderTarget ? bridge.exportToBlender : bridge.exportToUnreal;
      const result = await exportAssets({
        assetIds,
        options: {
          ...settings,
          exportResolution: activeExportResolutionValue,
          meshOverwritePolicy,
          blenderDecimationRatio: currentBlenderDecimationRatio,
          decalExportMode: currentDecalExportMode,
          plantExportMode: resolvePlantModeForAssets(assetIds.map(id => selectedAsset?.id === id ? selectedAsset : allAssets.find(asset => asset.id === id)), currentPlantExportMode),
          plantSyntheticWind: currentPlantSyntheticWind
        }
      });
      const feedback = getEngineImportFeedback(result, isBlenderTarget, t);
      showExportStatus(feedback.text, feedback.durationMs, feedback.detail);
    } catch (error) {
      showExportStatus(t(`导入失败：${String(error)}`, `Import failed: ${String(error)}`), 10000);
    } finally {
      exportInFlightRef.current = false;
      setIsExporting(false);
      setImportingAssetIds([]);
      setExportProgress(0);
      setExportStage("");
    }
  }

  async function pickTargetPath() {
    if (isBlenderTarget && bridgeAvailable) {
      try {
        const hasBlenderPicker = typeof bridge.pickBlenderExecutable === "function";
        if (!hasBlenderPicker) setPluginInstallMessage(t("请选择包含 blender.exe 的 Blender 安装文件夹", "Select the Blender installation folder containing blender.exe"));
        const picked = hasBlenderPicker ? await bridge.pickBlenderExecutable()
          : await bridge.pickAssetFolder({ defaultPath: (settings.blenderExecutablePath || "").replace(/[\\/][^\\/]+$/, "") || undefined });
        if (picked) await saveBlenderPath(hasBlenderPicker ? picked : `${picked.replace(/[\\/]+$/, "")}\\blender.exe`);
      } catch (error) { setPluginInstallMessage(String(error)); showStatus(String(error), 10000); }
      return;
    }
    if (bridgeAvailable && bridge.pickTargetPath) {
      const pickTargetPath = (bridge as typeof bridge & {
        pickTargetPath?: () => Promise<{ type?: string; path?: string } | null>;
      }).pickTargetPath;
      const result = pickTargetPath ? await pickTargetPath() : null;
      if (result) {
        if (result.type === "engine") {
          const saved = await bridge.updateSettings({ unrealEditorPath: result.path, unrealProjectPath: "" });
          setSettings(saved);
        } else if (result.type === "project") {
          const saved = await bridge.updateSettings({ unrealProjectPath: result.path, unrealEditorPath: "" });
          setSettings(saved);
        }
      }
    }
  }

  async function saveBlenderPath(raw: string) {
    const executable = raw.trim().replace(/^"|"$/g, "").replace(/[\\/]+$/, "");
    if (executable && !/(?:^|[\\/])blender\.exe$/i.test(executable)) {
      setBlenderPathDraft(settings.blenderExecutablePath || "");
      showStatus(t("请选择 blender.exe，或输入它的完整路径", "Select blender.exe or enter its full path"), 6000);
      return;
    }
    if (!bridgeAvailable || executable === (settings.blenderExecutablePath || "")) return;
    if (executable && bridge.pathExists && !await bridge.pathExists(executable)) {
      setBlenderPathDraft(settings.blenderExecutablePath || "");
      showStatus(t("此路径下没有 blender.exe，请选择 Blender 的安装文件夹或程序文件", "No blender.exe found at this path. Select Blender's installation folder or executable"), 8000);
      return;
    }
    setBlenderStatus({ installed: false, connected: false });
    setSettings(await bridge.updateSettings({ blenderExecutablePath: executable }));
    setBlenderPathDraft(executable);
    setPluginInstallMessage("");
  }

  async function changeExportTarget(value: string) {
    if (!bridgeAvailable || isExporting || pluginInstalling) return;
    try {
      const target = value === "blender" ? "blender" : value === "3dcoat" ? "3dcoat" : "unreal";
      setSettings(await bridge.updateSettings({ exportTarget: target }));
      setPluginInstallMessage("");
      if (target === "3dcoat") setThreeDCoatStatusRevision(revision => revision + 1);
    } catch (error) { showStatus(String(error), 10000); }
  }

  async function pickThreeDCoatConnection(kind: "program" | "dataDirectory") {
    if (!bridgeAvailable || isExporting) return;
    try {
      const result = kind === "program" ? await bridge.pickThreeDCoatProgram() : await bridge.pickThreeDCoatDataDirectory();
      if (!result.ok) throw new Error(result.message);
      await refreshThreeDCoatStatus();
    } catch (error) { showStatus(String(error), 10000); }
  }

  async function saveThreeDCoatPath(raw: string) {
    const executable = raw.trim().replace(/^"|"$/g, "").replace(/[\\/]+$/, "");
    if (!bridgeAvailable || executable === (threeDCoatStatus.executable || "")) return;
    if (!/\.exe$/i.test(executable)) {
      setThreeDCoatPathDraft(threeDCoatStatus.executable || "");
      showStatus(t("请选择 3DCoat 的 .exe 程序文件", "Select the 3DCoat .exe application"), 6000);
      return;
    }
    if (!bridge.configureThreeDCoat) {
      setThreeDCoatPathDraft(threeDCoatStatus.executable || "");
      showStatus(t("请重启 AssetHive 后保存 3DCoat 路径", "Restart AssetHive to save the 3DCoat path"), 8000);
      return;
    }
    try {
      const result = await bridge.configureThreeDCoat({ executable });
      if (!result.ok) throw new Error(result.message);
      setThreeDCoatStatus({
        executable: result.executable || "", dataDirectory: result.dataDirectory || "",
        executableExists: Boolean(result.executableExists), dataDirectoryExists: Boolean(result.dataDirectoryExists),
        ready: Boolean(result.ready), mode: result.mode, language: result.language
      });
      setThreeDCoatStatusRevision(revision => revision + 1);
    } catch (error) {
      setThreeDCoatPathDraft(threeDCoatStatus.executable || "");
      showStatus(String(error), 8000);
    }
  }

  async function installTargetPlugin() {
    if (!bridgeAvailable || !exportTargetPath || pluginInstalling || isExporting) return;
    setPluginInstalling(true);
    setPluginInstallMessage(t("正在安装插件…", "Installing add-on…"));
    try {
      if (isBlenderTarget && typeof bridge.installBlenderPlugin !== "function") {
        setPluginInstallMessage(t("路径已保存，请重启 AssetHive 后安装 Blender 插件", "Path saved. Restart AssetHive to install the Blender add-on"));
        return;
      }
      const result = isBlenderTarget
        ? await bridge.installBlenderPlugin()
        : await bridge.installPlugin?.(settings.pluginRepo || "", exportTargetPath);
      const message = result?.ok
        ? isBlenderTarget
          ? t(`插件已安装到 ${result.path || ""}。已打开的 Blender 请重启一次。`, `Add-on installed to ${result.path || ""}. Restart Blender if it is open.`)
          : t("插件安装完成，请重启 Unreal Editor", "Plugin installed. Restart Unreal Editor")
        : result?.message || t("插件安装失败", "Add-on installation failed");
      setPluginInstallMessage(message);
      showStatus(message, result?.ok ? 6000 : 10000);
      if (isBlenderTarget) setBlenderStatusRevision(value => value + 1);
      else await refreshPluginStatus();
    } catch (error) { setPluginInstallMessage(String(error)); showStatus(String(error), 10000); }
    finally { setPluginInstalling(false); }
  }

  const pluginStatusRequestRef = useRef(0);
  const unrealTargetRef = useRef("");
  unrealTargetRef.current = `${settings.unrealEditorPath || ""}\n${settings.unrealProjectPath || ""}`;
  const refreshPluginStatus = useCallback(async (nextSettings?: AppSettings) => {
    const targetSettings = nextSettings || settings;
    const request = ++pluginStatusRequestRef.current;
    const targetKey = `${targetSettings.unrealEditorPath || ""}\n${targetSettings.unrealProjectPath || ""}`;
    const isCurrent = () => request === pluginStatusRequestRef.current && targetKey === unrealTargetRef.current;
    const editorPath = String(targetSettings.unrealEditorPath || "").trim();
    const projectPath = String(targetSettings.unrealProjectPath || "").trim();
    if (!bridgeAvailable || typeof bridge.getPluginStatus !== "function") {
      setPluginInstalled(false);
      setPluginStatusMessage("");
      setHasImportableProject(false);
      return;
    }
    // 空目标使用实时发现的工程；后端会从兼容握手返回 resolvedProjectPath。
    // 不在这里提前禁用，否则状态灯已连接时导出仍会一直是灰色。
    try {
      const result = await bridge.getPluginStatus({ editorPath, projectPath });
      if (!isCurrent()) return;
      const resolvedProjectPath = String((result as { resolvedProjectPath?: string } | null)?.resolvedProjectPath || "").trim();
      setPluginInstalled(Boolean(result?.installed && (result?.enabled ?? true)));
      setPluginStatusMessage(String(result?.message || ""));
      setHasImportableProject(Boolean(resolvedProjectPath || projectPath || editorPath));
    } catch (error) {
      if (!isCurrent()) return;
      setPluginInstalled(false);
      setPluginStatusMessage(String(error || ""));
      setHasImportableProject(false);
    }
  }, [bridge, bridgeAvailable, settings, setHasImportableProject, setPluginInstalled, setPluginStatusMessage]);

  const applyAppUpdateProgress = useCallback((payload?: AppUpdateDownloadProgress | null) => {
    const value = payload?.progress;
    setAppUpdateDownloadProgress(typeof value === "number" && Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : null);
    const loaded = Number(payload?.loaded);
    const total = Number(payload?.total);
    setAppUpdateDownloadedBytes(Number.isFinite(loaded) && loaded > 0 ? loaded : 0);
    setAppUpdateTotalBytes(Number.isFinite(total) && total > 0 ? total : 0);
  }, [setAppUpdateDownloadProgress, setAppUpdateDownloadedBytes, setAppUpdateTotalBytes]);

  const applyAppUpdateState = useCallback((state: AppUpdateSnapshot, progressRevision?: number) => {
    setAppUpdateState(prev => ({
      ...prev, checked: true,
      hasUpdate: Boolean(state.hasUpdate), updateReady: Boolean(state.updateReady),
      localPackagePath: state.localPackagePath || "",
      currentVersion: state.currentVersion || prev.currentVersion,
      latestVersion: state.latestVersion || prev.latestVersion,
      releaseUrl: state.releaseUrl || "", releaseName: state.name || "",
      publishedAt: state.publishedAt || "", releaseNotes: state.releaseNotes || "",
      repo: state.repo || "", downloadUrl: state.downloadUrl || "",
      packageSize: state.packageSize || 0
    }));
    const downloading = state.phase === "downloading";
    setAppUpdateMode(downloading ? "downloading" : "idle");
    setAppUpdateBusy(downloading);
    setAppUpdateMessage(state.message || "");
    if (downloading && progressRevision === appUpdateProgressRevision.current) {
      applyAppUpdateProgress(state.downloadProgress);
    }
  }, [applyAppUpdateProgress, setAppUpdateState, setAppUpdateMode, setAppUpdateBusy, setAppUpdateMessage]);

  useEffect(() => {
    if (!bridgeAvailable) return;
    let active = true;
    const stateRevision = appUpdateStateRevision.current;
    const progressRevision = appUpdateProgressRevision.current;
    const unsubscribeState = bridge.onAppUpdateState?.(state => {
      appUpdateStateRevision.current++;
      applyAppUpdateState(state);
      if (state.showPrompt) setUpdatePageOpen(true);
    });
    const unsubscribeProgress = bridge.onAppUpdateDownloadProgress?.(payload => {
      appUpdateProgressRevision.current++;
      applyAppUpdateProgress(payload);
    });
    // Subscribe before reading the snapshot so a newer event can supersede it.
    void bridge.checkAppUpdate?.().then(result => {
      if (active && result?.ok && stateRevision === appUpdateStateRevision.current) {
        applyAppUpdateState(result, progressRevision);
      }
    }).catch(() => {});
    return () => {
      active = false;
      unsubscribeState?.();
      unsubscribeProgress?.();
    };
  }, [bridge, bridgeAvailable, applyAppUpdateState, applyAppUpdateProgress, setUpdatePageOpen]);

  async function checkAppUpdate() {
    if (!bridgeAvailable || typeof bridge.checkAppUpdate !== "function") {
      setAppUpdateMessage(t("当前环境不支持检查更新", "Checking for updates is unavailable in this environment"));
      return;
    }
    setAppUpdateMode("checking");
    setAppUpdateBusy(true);
    setAppUpdateMessage(t("正在检查更新...", "Checking for updates..."));
    const stateRevision = appUpdateStateRevision.current;
    const progressRevision = appUpdateProgressRevision.current;
    try {
      const result = await bridge.checkAppUpdate();
      if (stateRevision !== appUpdateStateRevision.current) return;
      if (result?.ok) {
        applyAppUpdateState(result, progressRevision);
        return;
      }
      setAppUpdateMessage(result?.message || t("检查更新失败", "Update check failed"));
    } catch (error) {
      if (stateRevision !== appUpdateStateRevision.current) return;
      setAppUpdateMessage(t(`检查更新失败：${String(error)}`, `Update check failed: ${String(error)}`));
    }
    setAppUpdateMode("idle");
    setAppUpdateBusy(false);
  }

  async function downloadAppUpdate() {
    if (!bridgeAvailable || typeof bridge.downloadAppUpdate !== "function") {
      setAppUpdateMessage(t("当前环境不支持下载更新", "Downloading updates is unavailable in this environment"));
      return;
    }
    setAppUpdateMode("downloading");
    setAppUpdateDownloadProgress(0);
    setAppUpdateDownloadedBytes(0);
    setAppUpdateTotalBytes(0);
    setAppUpdateBusy(true);
    setAppUpdateMessage("");
    try {
      const result = await bridge.downloadAppUpdate();
      if (!result?.ok) {
        setAppUpdateMessage(result?.message || t("下载更新失败", "Update download failed"));
        return;
      }
      if (!result?.hasUpdate) {
        setAppUpdateMessage(result?.message || t("已经是最新版本", "Already up to date"));
        return;
      }
      setAppUpdateDownloadProgress(100);
      setAppUpdateState((prev) => ({
        ...prev,
        checked: true,
        hasUpdate: true,
        updateReady: Boolean(result?.updateReady),
        localPackagePath: String(result?.filePath || prev.localPackagePath || "")
      }));
      setAppUpdateMessage("");
      setStatus(t("更新包下载完成，请点击安装", "Update downloaded. Click Install to continue"));
    } catch (error) {
      setAppUpdateMessage(t(`下载更新失败：${String(error)}`, `Update download failed: ${String(error)}`));
    } finally {
      setAppUpdateMode("idle");
      setAppUpdateBusy(false);
    }
  }

  async function installDownloadedUpdatePackage() {
    if (importSaving || isExporting || busy) {
      setAppUpdateMessage(t("请等待导入、导出任务结束后再更新", "Wait for import and export tasks to finish before updating"));
      return;
    }
    const packagePath = String(appUpdateState.localPackagePath || "").trim();
    if (!packagePath) {
      setAppUpdateMessage(t("未找到可安装的本地更新包", "No local update package found"));
      return;
    }
    if (!bridgeAvailable || typeof bridge.installDownloadedUpdate !== "function") {
      setAppUpdateMessage(t("当前环境不支持安装更新包", "Installing updates is unavailable in this environment"));
      return;
    }
    setAppUpdateMode("installing");
    setAppUpdateBusy(true);
    setAppUpdateMessage(t("正在启动安装程序...", "Starting installer..."));
    try {
      const result = await bridge.installDownloadedUpdate({ filePath: packagePath });
      if (!result?.ok) {
        setAppUpdateMessage(result?.message || t("启动安装失败", "Failed to start installer"));
        return;
      }
      setAppUpdateMessage(result?.message || t("安装程序已启动", "Installer started"));
    } catch (error) {
      setAppUpdateMessage(t(`启动安装失败：${String(error)}`, `Failed to start installer: ${String(error)}`));
    } finally {
      setAppUpdateMode("idle");
      setAppUpdateBusy(false);
    }
  }

  useEffect(() => {
    // 插件状态没有事件源：迁移插件位置、切换项目、插件目录瞬间不可见，都可能让某一次
    // 检查得到 false，而 canExportToUnreal 直接由它控制（false 即导入入口禁用）。
    // 没有自愈路径时只能重启应用才能恢复，因此这里低频重新确认（两次文件存在性检查 +
    // 一次项目文件读取，代价可忽略）。
    return pollWindowStatus(() => refreshPluginStatus(), 8000);
  }, [refreshPluginStatus, settings.unrealEditorPath, settings.unrealProjectPath, unrealConnected, unrealConnectedTargetName]);

  useEffect(() => {
    if (!bridgeAvailable || typeof bridge.getUnrealConnectionStatus !== "function") {
      setUnrealConnected(false);
      setUnrealConnectedTargetName("");
      setUnrealConnectionMessage("");
      return;
    }
    let disposed = false;
    const updateConnectionStatus = async () => {
      try {
        const result = await bridge.getUnrealConnectionStatus();
        if (disposed) {
          return;
        }
        setUnrealConnected(Boolean(result?.connected));
        setConnectedUeProjectPath(String(result?.projectPath || ''));
        setConnectedUeProjectId(String(result?.projectId || '').replace(/[{}-]/g, '').toLowerCase());
        setUnrealConnectedTargetName(String(result?.targetName || "").trim());
        setUnrealConnectionMessage(String(result?.message || "").trim());
      } catch {
        if (!disposed) {
          setUnrealConnected(false);
          setUnrealConnectedTargetName("");
          setUnrealConnectionMessage(t("连接状态读取失败，将自动重试", "Could not read connection status. Retrying automatically"));
        }
      }
    };
    const stop = pollWindowStatus(updateConnectionStatus, 4000);
    return () => {
      disposed = true;
      stop();
    };
  }, [bridge, bridgeAvailable, settings.unrealProjectPath, settings.unrealEditorPath, setUnrealConnected, setUnrealConnectedTargetName, setUnrealConnectionMessage, t]);

  function selectImportCover(form: ImportFormState, previewImagePath: string): ImportFormState {
    if (!isCharacterAssetType(form.assetType)) return { ...form, previewImagePath };
    const automatic = Object.values(form.characterPreviewPaths);
    const custom = [form.previewImagePath, previewImagePath].filter(path => path && !automatic.includes(path));
    return { ...form, previewImagePath, characterExtraPreviewPaths: [...new Set([...(form.characterExtraPreviewPaths || []), ...custom])],
      characterFields: { ...form.characterFields, confirmed: false } };
  }

  async function pickImportPreview() {
    if (!bridgeAvailable) {
      showStatus(t("导入资产需要桌面端环境，请运行 npm run dev", "Importing assets requires the desktop app. Run npm run dev"), 10000);
      return;
    }
    const picked = await bridge.pickAssetImage();
    if (picked) {
      setImportForm(prev => selectImportCover(prev, picked));
    }
  }

  async function generateCharacterPreviewForForm(draft: ImportFormState, requestId = "") {
    setCharacterPreviewProgress({ done: 0, total: 0 });
    if (!bridgeAvailable || typeof bridge.materializeDroppedFile !== "function") {
      throw new Error(t("生成角色预览需要桌面端环境", "Character preview generation requires the desktop app"));
    }
    const modelPaths = [...new Set(Object.values(draft.modelSlots).map((value) => String(value || "").trim()).filter((value) => /\.fbx$/i.test(value) && !/_LOD[1-9]\d*\.fbx$/i.test(value)))];
    if (modelPaths.length === 0) {
      const groom = draft.assetType === 'suit' && draft.characterFields.variant === 'Hair'
        ? Object.values(draft.modelSlots).find(file => /\.abc$/i.test(file)) : undefined;
      if (groom && bridge.renderGroomPreview) {
        const paths = await bridge.renderGroomPreview(groom);
        if (requestId && quickDropRequestIdRef.current !== requestId) return draft;
        return { ...draft, previewImagePath: draft.previewImagePath || paths.front, characterPreviewPaths: paths,
          characterFields: { ...draft.characterFields, confirmed: false } };
      }
      throw new Error(t("未识别到可生成预览的 FBX 模型", "No FBX models were detected for preview generation"));
    }
    const texturePaths = draft.characterPackageFiles.filter((filePath) => /\.(?:png|jpe?g|tiff?|tga|webp|bmp)$/i.test(filePath));
    const previewTextures = await Promise.all(texturePaths.map(async (sourcePath) => {
      if (typeof bridge.getPreviewThumbnail !== "function") return { sourcePath, previewPath: sourcePath };
      try { return { sourcePath, previewPath: String(await bridge.getPreviewThumbnail(sourcePath, { character: true }) || sourcePath) }; }
      catch { return { sourcePath, previewPath: sourcePath }; }
    }));
    if (requestId && quickDropRequestIdRef.current !== requestId) return draft;
    const partPreviews: NonNullable<ImportFormState['characterPartPreviews']> = [];
    const saveViews = async (blobs: Record<typeof CHARACTER_PREVIEW_VIEWS[number], Blob>, prefix: string) => {
      const result = { front: '', left: '', right: '', back: '' };
      for (const view of CHARACTER_PREVIEW_VIEWS) {
        if (requestId && quickDropRequestIdRef.current !== requestId) throw new Error('预览任务已取消');
        const tempPath = await bridge.materializeDroppedFile!({ name: `${prefix}_${view}.png`, bytes: await blobs[view].arrayBuffer() });
        if (!tempPath) throw new Error(`无法保存 ${view} 临时预览`);
        result[view] = tempPath;
      }
      return result;
    };
    const blobs = await generateCharacterImportPreviews(modelPaths.map(sourcePath => ({ sourcePath,
      meshKind: draft.characterModelAnalysis[sourcePath]?.meshKind || 'staticMesh' })), previewTextures,
      async (sourcePath, meshKind, images) => {
        partPreviews.push({ sourcePath, sourceHash: draft.characterModelAnalysis[sourcePath]?.sourceHash, meshKind, paths: await saveViews(images, `part_${partPreviews.length}`) });
      }, (done, total) => {
        if (requestId && quickDropRequestIdRef.current !== requestId) throw new Error('预览任务已取消');
        setCharacterPreviewProgress({ done, total });
        setQuickDropProgress(Math.round(done / total * 100));
      }, {
        partPaths: new Set(modelPaths.filter(file => draft.assetType === 'weapon' || draft.assetType === 'suit'
          || draft.assetType === 'monster' && /_WP_/i.test(file.split(/[\\/]/).pop() || ''))),
        texturedOwner: draft.assetType !== 'suit' || Boolean(heroPartKind(draft.characterFields)),
        heroPart: heroPartKind(draft.characterFields),
        separateModels: draft.assetType === 'weapon'
      });
    const paths = { front: "", left: "", right: "", back: "" };
    for (const view of CHARACTER_PREVIEW_VIEWS) {
      if (requestId && quickDropRequestIdRef.current !== requestId) return draft;
      const bytes = await blobs[view].arrayBuffer();
      const tempPath = await bridge.materializeDroppedFile({
        name: `${String(draft.assetName || "character").replace(/[\\/:*?"<>|]/g, "_")}_${view}.png`, bytes
      });
      if (!tempPath) throw new Error(`无法保存 ${view} 临时预览`);
      paths[view] = tempPath;
    }
    return { ...draft, previewImagePath: draft.previewImagePath || paths.front, characterPreviewPaths: paths, characterPartPreviews: partPreviews,
      characterFields: { ...draft.characterFields, confirmed: false } };
  }

  async function pickEditPreview() {
    if (!bridgeAvailable) {
      showStatus(t("编辑资产需要桌面端环境，请运行 npm run dev", "Editing assets requires the desktop app. Run npm run dev"), 10000);
      return;
    }
    const picked = await bridge.pickAssetImage();
    if (picked) {
      setEditForm((prev) => ({ ...prev, previewImagePath: picked }));
    }
  }

  function isMeshSlotKey(slotKey: string) {
    return /^mesh(?:\d+)?$/i.test(String(slotKey || "").trim());
  }

  function getMeshSlotOrder(slotKey: string) {
    const normalized = String(slotKey || "").trim();
    if (!normalized) {
      return Number.MAX_SAFE_INTEGER;
    }
    if (/^mesh$/i.test(normalized)) {
      return 1;
    }
    const matched = normalized.match(/^mesh(\d+)$/i);
    if (!matched) {
      return Number.MAX_SAFE_INTEGER;
    }
    const parsed = Number(matched[1]);
    return Number.isFinite(parsed) ? parsed : Number.MAX_SAFE_INTEGER;
  }

  function formatMeshSlotKey(order: number) {
    if (order <= 1) {
      return meshSlotBaseName;
    }
    return `${meshSlotBaseName}${String(order).padStart(2, "0")}`;
  }

  function getOrderedMeshSlotKeys(modelSlots: Record<string, string>) {
    const keys = Object.keys(modelSlots).filter((slotKey) => isMeshSlotKey(slotKey));
    keys.sort((a, b) => getMeshSlotOrder(a) - getMeshSlotOrder(b));
    return keys;
  }

  function getDisplayMeshSlotKeys(modelSlots: Record<string, string>) {
    const ordered = getOrderedMeshSlotKeys(modelSlots);
    if (ordered.length > 0) {
      return ordered;
    }
    return [meshSlotBaseName];
  }

  function getNextMeshSlotKey(modelSlots: Record<string, string>) {
    const ordered = getOrderedMeshSlotKeys(modelSlots);
    if (ordered.length === 0) {
      return meshSlotBaseName;
    }
    const maxOrder = Math.max(...ordered.map((slotKey) => getMeshSlotOrder(slotKey)).filter((value) => Number.isFinite(value)));
    return formatMeshSlotKey((Number.isFinite(maxOrder) ? maxOrder : 1) + 1);
  }

  // Display label for the mesh slot, e.g. "Mesh Slot 01".
  function getMeshSlotLabel(slotKey: string) {
    const order = getMeshSlotOrder(slotKey);
    if (!Number.isFinite(order) || order < 1 || order >= Number.MAX_SAFE_INTEGER) {
      return "Mesh Slot 01";
    }
    return `Mesh Slot ${String(order).padStart(2, "0")}`;
  }

  // Sentence-friendly phrase for status / tooltip text ("变体 1" / "variant 1").
  function getMeshSlotPhrase(slotKey: string) {
    const order = getMeshSlotOrder(slotKey);
    const number = (Number.isFinite(order) && order >= 1 && order < Number.MAX_SAFE_INTEGER) ? String(order) : "1";
    return t(`变体 ${number}`, `variant ${number}`);
  }

  function normalizeImportModelVariantKey(value: string) {
    let raw = String(value || "").trim();
    const prefixed = raw.match(/^(?:var(?:iant)?|variation)[\s._-]*(.+)$/i);
    if (prefixed) raw = prefixed[1];
    raw = raw.replace(/[^A-Za-z0-9]+/g, "");
    if (!raw) return "";
    if (/^\d+$/.test(raw)) {
      const numeric = Number(raw);
      return Number.isFinite(numeric) && numeric > 0 ? String(Math.floor(numeric)).padStart(2, "0") : "";
    }
    return raw.toUpperCase().slice(0, 32);
  }

  function parseImportModelVariantKey(filePath: string) {
    const stem = getFileStemFromPath(filePath);
    if (!stem) return "";
    const named = [...stem.matchAll(/(?:^|[_\-. ])(?:var(?:iant)?|variation)[_\-.\s]*([A-Za-z0-9]{1,6})(?=$|[_\-. ])/gi)].at(-1)?.[1] || "";
    if (named) return normalizeImportModelVariantKey(named);
    const beforeLod = stem.match(/(?:^|[_\-. ])([A-Za-z0-9]{1,6})[_\-. ]*lod(?:[_-]?\d+)?(?:$|[_\-. ])/i)?.[1] || "";
    if (beforeLod) return normalizeImportModelVariantKey(beforeLod);
    const withoutLod = stem.replace(/(?:^|[_\-. ])lod(?:[_-]?\d+)?(?=$|[_\-. ])/gi, "").replace(/[_\-. ]+$/g, "");
    const trailing = withoutLod.match(/(?:^|[_\-. ])([A-Za-z0-9]{1,6})$/)?.[1] || "";
    return trailing ? normalizeImportModelVariantKey(trailing) : "";
  }

  function stripImportModelLodKey(filePath: string) {
    const stem = getFileStemFromPath(filePath)
      .replace(/(?:^|[_\-. ])lod(?:[_-]?\d+)?(?=$|[_\-. ])/gi, "")
      .replace(/[_\-. ]+$/g, "");
    return stem.toLowerCase().replace(/[_.\s-]+/g, "");
  }

  function buildImportModelLodFiles(
    sourceFiles: string[],
    metadataModelLods: Array<Record<string, unknown>>,
    modelSlots: Record<string, string>,
    modelVariantKeys: Record<string, string>
  ) {
    const slotKeys = Object.keys(modelSlots).filter((slotKey) => String(modelSlots[slotKey] || "").trim());
    if (slotKeys.length === 0) return {} as Record<string, ModelLodEntry[]>;

    const slotByVariant = new Map<string, string>();
    const slotByBase = new Map<string, string>();
    for (const slotKey of slotKeys) {
      const variantKey = normalizeImportModelVariantKey(modelVariantKeys[slotKey] || parseImportModelVariantKey(modelSlots[slotKey]));
      if (variantKey && !slotByVariant.has(variantKey)) slotByVariant.set(variantKey, slotKey);
      const baseKey = stripImportModelLodKey(modelSlots[slotKey]);
      if (baseKey && !slotByBase.has(baseKey)) slotByBase.set(baseKey, slotKey);
    }

    const candidates: Array<{ filePath: string; lod: number; variantKey: string }> = [];
    const seen = new Set<string>();
    const addCandidate = (filePath: unknown, lodValue: unknown, variantValue: unknown) => {
      const normalizedPath = normalizeLocalPath(String(filePath || "").trim());
      if (!normalizedPath || !/\.fbx$/i.test(normalizedPath)) return;
      const key = normalizedPath.toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      const lod = Number.isFinite(Number(lodValue)) ? Math.max(0, Math.floor(Number(lodValue))) : getModelLodOrder(normalizedPath);
      if (!Number.isFinite(lod) || lod === Number.MAX_SAFE_INTEGER) return;
      candidates.push({
        filePath: normalizedPath,
        lod,
        variantKey: normalizeImportModelVariantKey(String(variantValue || "")) || parseImportModelVariantKey(normalizedPath)
      });
    };

    for (const item of Array.isArray(metadataModelLods) ? metadataModelLods : []) {
      addCandidate(item?.file || item?.path || item?.uri, item?.lod, item?.variantKey ?? item?.variantNumber ?? item?.variation ?? item?.variant);
    }
    for (const filePath of sourceFiles) {
      if (isModelLodPath(filePath)) addCandidate(filePath, getModelLodOrder(filePath), "");
    }

    const result: Record<string, ModelLodEntry[]> = {};
    for (const candidate of candidates) {
      const owner = slotByVariant.get(candidate.variantKey)
        || slotByBase.get(stripImportModelLodKey(candidate.filePath))
        || (slotKeys.length === 1 ? slotKeys[0] : "");
      if (!owner) continue;
      const entries = result[owner] || [];
      if (!entries.some((entry) => normalizeLocalPath(entry.filePath).toLowerCase() === candidate.filePath.toLowerCase())) {
        entries.push({ filePath: candidate.filePath, lod: candidate.lod });
      }
      result[owner] = entries;
    }

    for (const [slotKey, entries] of Object.entries(result)) {
      const primaryPath = normalizeLocalPath(modelSlots[slotKey] || "");
      if (primaryPath && !isModelLodPath(primaryPath) && !entries.some((entry) => entry.lod === 0)) {
        entries.push({ filePath: primaryPath, lod: 0 });
      }
      entries.sort((left, right) => left.lod - right.lod || left.filePath.localeCompare(right.filePath, undefined, { numeric: true, sensitivity: "base" }));
    }
    return result;
  }

  function formatTextureAreaOrder(order: number) {
    return String(Math.max(1, Number(order) || 1)).padStart(3, "0");
  }

  function getTextureAreaIdList(entries: TextureEntry[]) {
    const ids = [...new Set(entries.map((entry) => Math.max(1, Number(entry.areaId) || 1)))];
    ids.sort((a, b) => a - b);
    return ids.length > 0 ? ids : [1];
  }

  function getTextureSlotToken(textureType: string, areaId: number, areaCount: number, entryId?: string, materialRole?: TextureMaterialRole) {
    const normalizedType = String(textureType || "").trim();
    if (!normalizedType) {
      return "";
    }
    const shouldAttachDisplacementEntryId = () => {
      if (normalizedType.toLowerCase() !== "displacement") {
        return false;
      }
      const id = String(entryId || "").trim();
      if (!id) {
        return false;
      }
      return id.startsWith("import-default-") || id.startsWith("edit-default-");
    };
    const suffix = shouldAttachDisplacementEntryId() ? `_${String(entryId || "").trim()}` : "";
    const roleSuffix = materialRole ? `|${materialRole}` : "";
    if (areaCount <= 1) {
      return `${normalizedType}${suffix}${roleSuffix}`;
    }
    return `${formatTextureAreaOrder(areaId)}_${normalizedType}${suffix}${roleSuffix}`;
  }

  function parseTextureSlotToken(value: string) {
    const raw = String(value || "").trim();
    const prefixed = raw.match(/^(\d{3})[_-](.+)$/);
    if (prefixed) {
      const areaId = Math.max(1, Number(prefixed[1]) || 1);
      const textureType = String(prefixed[2] || "").trim();
      return { areaId, textureType: normalizeOpacityTextureType(textureType) };
    }
    return { areaId: 1, textureType: normalizeOpacityTextureType(raw) };
  }

  function inferTextureAreaIdFromPath(filePath: string) {
    const baseName = String(filePath || "").split(/[\\/]/).pop() || "";
    const matched = baseName.match(/_(\d{3})_[^_.]+(?:\.[^.]+)?$/i);
    if (!matched) {
      return 1;
    }
    const parsed = Number(matched[1]);
    return Number.isFinite(parsed) && parsed >= 1 ? parsed : 1;
  }

  async function pickImportModel(modelType: string) {
    if (!bridgeAvailable) {
      showStatus(t("导入资产需要桌面端环境，请运行 npm run dev", "Importing assets requires the desktop app. Run npm run dev"), 10000);
      return;
    }
    let picked = "";
    const pickKind = isAnimationAssetImportType(importForm.assetType) ? "animation" : importForm.assetType === "suit" && importForm.characterFields.variant === "Hair" ? "hairModel" : "model";
    if (typeof bridge.pickAssetFile === "function") {
      picked = (await bridge.pickAssetFile(pickKind)) || "";
      if (!picked) {
        showStatus(t(`未选择${getImportFileSlotPhrase(importForm.assetType, modelType)}的文件`, `No file selected for ${getImportFileSlotPhrase(importForm.assetType, modelType)}`), 10000);
        return;
      }
    } else {
      picked = await pickFileByInput(getAcceptedModelExtsForAssetType(importForm.assetType, importForm.characterFields).map(ext => "." + ext).join(","));
    }
    if (picked && !isModelFileAcceptedForType(picked, importForm.assetType, importForm.characterFields)) {
      showStatus(t(`${getImportFileSlotPhrase(importForm.assetType, modelType)} 不支持该格式（允许：${formatAcceptedModelExts(importForm.assetType, importForm.characterFields)}）`, `Unsupported format for ${getImportFileSlotPhrase(importForm.assetType, modelType)} (allowed: ${formatAcceptedModelExts(importForm.assetType, importForm.characterFields)})`), 10000);
      return;
    }
    if (picked) {
      setImportForm((prev) => applyImportedModelFile(prev, modelType, picked));
      return;
    }
    showStatus(t(`未选择${getImportFileSlotPhrase(importForm.assetType, modelType)}的文件`, `No file selected for ${getImportFileSlotPhrase(importForm.assetType, modelType)}`), 10000);
  }

  async function pickImportTexture(entryId: string) {
    if (!bridgeAvailable) {
      showStatus(t("导入资产需要桌面端环境，请运行 npm run dev", "Importing assets requires the desktop app. Run npm run dev"), 10000);
      return;
    }
    const entry = importForm.textureEntries.find((item) => item.id === entryId);
    if (!entry) return;
    const textureType = String(entry.textureType || "").trim();
    const isDisplacement = textureType.toLowerCase() === "displacement";
    let picked = "";
    if (typeof bridge.pickAssetFile === "function") {
      const acceptType = importForm.assetType === "hdri" ? "hdri" : (isDisplacement ? "displacement" : "texture");
      picked = (await bridge.pickAssetFile(acceptType)) || "";
      if (!picked) {
        showStatus(t("未选择贴图文件", "No texture file selected"), 10000);
        return;
      }
    } else {
      const extensions = getAcceptedTextureExtsForAssetType(importForm.assetType, textureType).map((ext) => `.${ext}`).join(",");
      picked = await pickFileByInput(extensions);
    }
    if (picked && !isTextureFileAccepted(picked, importForm.assetType, textureType)) {
      const exts = getAcceptedTextureExtsForAssetType(importForm.assetType, textureType).join(", ");
      showStatus(t(`贴图格式无效（允许：${exts}）`, `Invalid texture format (allowed: ${exts})`), 10000);
      return;
    }
    if (picked && !isTextureWithinImportResolutionLimit(picked)) {
      const fileName = picked.split(/[\\/]/).pop() || picked;
      showStatus(t(`贴图超过 8K 限制：${fileName}`, `Texture exceeds the 8K limit: ${fileName}`), 10000);
      return;
    }
    if (picked) {
      setImportForm((prev) => ({
        ...prev,
        textureEntries: prev.textureEntries.map((item) => item.id === entryId ? { ...item, filePath: picked } : item)
      }));
      return;
    }
    showStatus(t("未选择贴图文件", "No texture file selected"), 10000);
  }

