  async function resolveDroppedFilePath(file: (File & { path?: string }) | null | undefined) {
    if (!file) {
      return "";
    }
    if (file.path) {
      return file.path;
    }
    if (bridgeAvailable && typeof bridge.getDroppedFilePath === "function") {
      try {
        const resolvedPath = String(bridge.getDroppedFilePath(file) || "").trim();
        if (resolvedPath) {
          return resolvedPath;
        }
      } catch {
        void 0;
      }
    }
    if (bridgeAvailable && typeof bridge.materializeDroppedFile === "function") {
      try {
        const bytes = await file.arrayBuffer();
        const materialized = String(await bridge.materializeDroppedFile({
          name: file.name || "dropped-file.bin",
          bytes
        }) || "").trim();
        if (materialized) {
          return materialized;
        }
      } catch {
        void 0;
      }
    }
    return "";
  }

  async function readDroppedPath(event: React.DragEvent<HTMLDivElement>) {
    event.preventDefault();
    event.stopPropagation();
    const dataTransfer = event.dataTransfer;
    const transferFiles = Array.from(dataTransfer.files || []) as Array<File & { path?: string }>;
    // FileList and items describe the same files. Query virtual ZIP files only
    // once; getAsFile is a fallback for sources that do not populate FileList.
    const itemFiles = transferFiles.length ? [] : Array.from(dataTransfer.items || [])
      .map((item) => item.getAsFile() as File & { path?: string } | null)
      .filter((file): file is File & { path?: string } => Boolean(file));
    const fileCandidates = [...transferFiles, ...itemFiles];
    const dedupedFiles = Array.from(new Map(fileCandidates.map((file) => [
      `${file.name || ""}|${file.size || 0}|${file.type || ""}|${file.lastModified || 0}`,
      file
    ])).values());
    for (const droppedFile of dedupedFiles) {
      const resolvedPath = await resolveDroppedFilePath(droppedFile);
      if (resolvedPath) {
        return resolvedPath;
      }
    }
    const transferTexts = [
      dataTransfer.getData("text/uri-list"),
      dataTransfer.getData("text/plain"),
      dataTransfer.getData("text"),
      dataTransfer.getData("DownloadURL")
    ].filter(Boolean);
    for (const rawText of transferTexts) {
      const normalizedLine = String(rawText)
        .split(/\r?\n/)
        .map((line) => line.trim())
        .find((line) => line && !line.startsWith("#")) || "";
      if (!normalizedLine) {
        continue;
      }
      const fromDownloadUrl = normalizedLine.includes("file://")
        ? normalizedLine.slice(normalizedLine.indexOf("file://"))
        : normalizedLine;
      const cleaned = fromDownloadUrl.split("\0").join("").replace(/^"|"$/g, "");
      if (!cleaned) {
        continue;
      }
      try {
        return normalizeLocalPath(decodeURIComponent(cleaned));
      } catch {
        return normalizeLocalPath(cleaned);
      }
    }
    return "";
  }

  function normalizeLocalPath(filePath: string) {
    const trimmed = String(filePath || "").trim().replace(/^"|"$/g, "");
    const fromUri = trimmed.replace(/^file:\/+/i, "");
    const withUnc = /^[a-zA-Z]:/.test(fromUri) ? fromUri : (trimmed.toLowerCase().startsWith("file://") ? `\\\\${fromUri}` : fromUri);
    const withoutLeading = withUnc.replace(/^\/([a-zA-Z]:[\\/])/, "$1");
    return withoutLeading.replace(/\//g, "\\");
  }

  function normalizeTextureMaterialRole(value: unknown, filePath = ""): TextureMaterialRole | undefined {
    const explicit = String(value || "").trim().toLowerCase();
    if (explicit === "atlas" || explicit === "billboard") {
      return explicit;
    }
    const normalizedPath = String(filePath || "").trim().replace(/\\/g, "/").toLowerCase();
    if (!normalizedPath) {
      return undefined;
    }
    const segments = normalizedPath.split("/").filter(Boolean);
    if (segments.some((segment) => /^(?:billboard|billboards)$/i.test(segment))
      || /(?:^|[_.-])billboard(?:[_.-]|$)/i.test(normalizedPath)) {
      return "billboard";
    }
    if (segments.some((segment) => /^(?:atlas|atlases)$/i.test(segment))
      || /(?:^|[_.-])atlas(?:[_.-]|$)/i.test(normalizedPath)) {
      return "atlas";
    }
    return undefined;
  }

  function isThumbsFolderPath(value: string) {
    const normalized = String(value || "").trim().replace(/\\/g, "/");
    return normalized.split("/").filter(Boolean).some((segment) => /^(?:thumb|thumbs|thumbnail|thumbnails)$/i.test(segment));
  }

  function makeTextureEntry(textureType = "", filePath = "", areaId = 1, materialRole?: TextureMaterialRole) {
    return {
      id: `${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
      textureType: normalizeOpacityTextureType(textureType),
      filePath,
      areaId: Math.max(1, Number(areaId) || 1),
      ...(materialRole ? { materialRole } : {})
    };
  }

  function ensureMaskTextureEntries(entries: TextureEntry[]) {
    const result = [...entries];
    for (const areaId of getTextureAreaIdList(entries)) {
      for (const type of ["Diffuse", "Normal", "ORM", "Mask", "UV2AO"]) {
        if (!result.some(entry => (entry.areaId || 1) === areaId && entry.textureType === type)) {
          result.push(makeTextureEntry(type, "", areaId));
        }
      }
    }
    return result;
  }

