  function reindexTextureAreas(entries: TextureEntry[]) {
    const areaIds = getTextureAreaIdList(entries);
    const areaIdMap = new Map(areaIds.map((areaId, index) => [areaId, index + 1]));
    return entries.map((entry) => ({
      ...entry,
      areaId: areaIdMap.get(Math.max(1, Number(entry.areaId) || 1)) || 1
    }));
  }

  function reindexTextureAreaValues<T>(values: Record<string, T> | undefined, remaining: TextureEntry[], fallback: T) {
    return Object.fromEntries(getTextureAreaIdList(remaining)
      .map((oldId, index) => [String(index + 1), values?.[oldId] ?? fallback]));
  }

  function removeImportTextureArea(areaId: number) {
    setImportForm((prev) => {
      const filtered = prev.textureEntries.filter((entry) => Math.max(1, Number(entry.areaId) || 1) !== areaId);
      const reindexedEntries = reindexTextureAreas(filtered);
      const nextNormalMapFormats = normalizeNormalMapFormatsByArea(
        reindexTextureAreaValues(prev.normalMapFormats, filtered, prev.normalMapFormat), reindexedEntries, prev.normalMapFormat);
      return {
        ...prev,
        textureEntries: reindexedEntries,
        materialNames: reindexTextureAreaValues(prev.materialNames, filtered, ""),
        maskGroups: reindexTextureAreaValues(prev.maskGroups, filtered, defaultMaskGroup()),
        normalMapFormats: nextNormalMapFormats
      };
    });
  }

