  function addImportTag(rawValue: string) {
    const tag = normalizeAssetTag(String(rawValue || ""));
    if (!tag) {
      return;
    }
    if (selectedImportIndexes.size > 1) {
      applyImportBatchPatch((form) => ({
        ...form,
        tagsText: [...new Set([...parseTagsText(form.tagsText), tag])].join(", ")
      }));
    } else {
      const nextTags = [...new Set([...parseTagsText(importForm.tagsText), tag])];
      syncImportTags(nextTags);
    }
    setImportTagInput("");
  }

  function removeImportTag(tagToRemove: string) {
    if (selectedImportIndexes.size > 1) {
      applyImportBatchPatch((form) => ({
        ...form,
        tagsText: parseTagsText(form.tagsText).filter((tag) => tag !== tagToRemove).join(", ")
      }));
      return;
    }
    const nextTags = parseTagsText(importForm.tagsText).filter((tag) => tag !== tagToRemove);
    syncImportTags(nextTags);
  }

