  async function copyAssetId(assetId: string) {
    const value = String(assetId || "").trim();
    if (!value) {
      showStatus(t("资产ID为空，无法复制", "No asset ID to copy"), 10000);
      return;
    }
    try {
      if (bridgeAvailable && typeof bridge.copyText === "function") {
        await bridge.copyText(value);
      } else if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(value);
      } else {
        showStatus(t("当前环境不支持复制功能", "Copying is unavailable in this environment"), 10000);
        return;
      }
      showStatus(t(`已复制资产ID：${value}`, `Asset ID copied: ${value}`), 2500);
    } catch (error) {
      showStatus(t(`复制资产ID失败：${String(error)}`, `Failed to copy asset ID: ${String(error)}`), 10000);
    }
  }

